return {
[54781] = {id=54781,name="What's For Lunch?",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="My Shadowtrade Mercenaries will fight for Stormarion Cores , no questions asked, but they do get hungry also! Food is quite scarce here, so we need supplies! Take a mercenary out with you and find some food for them to eat. I'll make it worth your while!",objectivesText="Slay Lurking Stormrays for 6 Stormray Fins and search Stormarion Supply crates for 6 Domanaar Snack Packs . Progress: Is that mercenary well fed?",starts={{mapID=2405,npcID=244749,x=0.264,y=0.675}},ends={{mapID=2405,npcID=244749,x=0.264,y=0.675}},coords={mapID=2405,source="quest_giver",x=0.264,y=0.675},questType="world",worldTaskTitle="What's For Lunch?"},
[76308] = {id=76308,name="The Trial of Style",faction="both",expansion=11,zoneID=1519,mapID=2393,description="Well, that's certainly an... interesting look, <class>. Me? Judgmental? Certainly not. However, I'm curious what others would think of it. You should speak to the Transmogrifier over there and enter the Trial of Style. We'll see what public opinion says about your choice in garb.",objectivesText="Speak to a Transmogrifier to enter and complete the Trial of Style. Progress: Ugh, I'm so bored. Did you complete the Trial of Style yet?",starts={{mapID=84,npcID=206252,x=0.51,y=0.725},{mapID=85,npcID=206383,x=0.488,y=0.765},{mapID=2339,npcID=236405,x=0.455,y=0.527}},ends={{mapID=84,npcID=206252,x=0.51,y=0.725},{mapID=85,npcID=206383,x=0.488,y=0.765},{mapID=2339,npcID=236405,x=0.455,y=0.527},{mapID=2393,npcID=258350,x=0.522,y=0.585}},coords={mapID=84,source="quest_giver",x=0.51,y=0.725},questType="world",worldTaskTitle="The Trial of Style"},
[86810] = {id=86810,name="Harvesting the Void",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="To effectively counteract the void anomalies present here, we must obtain viable samples of the anomalies. Search the area for containment vessels that hold developing anomalies, as well as the Unstable Oozelings created from the contamination. Use the collection device to make this process easier. Only living Oozelings will provide viable samples.",objectivesText="Collect 20 Anomaly Samples. Progress: Have you collected the necessary samples?",starts={{npcID=248114,x=0.268,y=0.68,zoneID=15458}},ends={{npcID=248114,x=0.268,y=0.68,zoneID=15458}},coords={x=0.268,y=0.68,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="Harvesting the Void"},
[86832] = {id=86832,name="A Worthy Forge",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Thank you for all your help, $p. It's strange to hold what remains of my father's shield and know that, prior to that day, he was such a defender of others. I feel I've only seen his aggressive side. I realize he means well, but I don't think... That is not the path for me. Regardless, let's return to Silvermoon and get these fragments we've gathered to a worthy forge.",objectivesText="Return to Silvermoon. Progress: <name>, I can't thank you enough for taking this journey with Arator and I.",starts={{npcID=237508,x=0.366,y=0.51,zoneID=46}},ends={{npcID=237511,x=0.456,y=0.654,zoneID=15969}},coords={x=0.366,y=0.51,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="A Worthy Forge"},
[86833] = {id=86833,name="A Bulwark Remade",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15969,mapID=2393,description="$p, it is time to see what we can do with these fragments of Turalyon's shield. While it did break, it was exceptionally powerful in its day, and it could be a great help to Turalyon against the Void. Perhaps a moment of healing and letting go, as well.",objectivesText="Help Arator reforge his father's shield. Progress: Thank you for helping me with this, <name>.",starts={{npcID=237511,x=0.456,y=0.654,zoneID=15969}},ends={{npcID=237510,x=0.406,y=0.66,zoneID=15969}},coords={x=0.456,y=0.654,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="A Bulwark Remade"},
[86837] = {id=86837,name="Meet at the Sunwell",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16215,mapID=2424,description="I have been tasked with bolstering the Vanguard of Light that empower the Sunwell. I need your help, though not just for that simple task. Our mutual friend, Arator , is... stuck. Stuck in his grief and anger over that tragic conflict between him and his father. I'm just an old priest that's been raised from the dead, but I've found that a quest is just the thing to set a young paladin back on the right path. Would you help?",objectivesText="Ask Arator to meet Faol at the Sunwell.",starts={{npcID=237565,x=0.456,y=0.658,zoneID=15969}},ends={{npcID=240240,x=0.528,y=0.552,zoneID=16215}},coords={x=0.456,y=0.658,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Meet at the Sunwell"},
[86838] = {id=86838,name="Renewal for the Weary",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16215,mapID=2424,description="The Vanguard of Light are maintaining a difficult ritual at the Sunwell. It requires focus, discipline, and is quite exhausting. Take my staff. I've had it since I was Archbishop in Stormwind. It is meaningful to me and my faith. The Light responds to meaning and intention. It should renew the Vanguard's spirits so they can maintain the ritual a while longer. I can't approach any closer to the Sunwell, so you will have to do this for me.",objectivesText="Restore the Light to 10 weary channelers.",starts={{npcID=240240,x=0.528,y=0.552,zoneID=16215}},ends={{npcID=240240,x=0.528,y=0.552,zoneID=16215}},coords={x=0.528,y=0.552,source="quest_giver",zoneID=16215},questType="world",worldTaskTitle="Renewal for the Weary"},
[86874] = {id=86874,name="Culling the Light",level=83,requiredLevel=83,faction="horde",expansion=11,zoneID=15355,mapID=2413,objectivesText="Lightbloom curbed",starts={{npcID=237356,x=0.306,y=0.772,zoneID=15355}},ends={{npcID=237356,x=0.306,y=0.772,zoneID=15355}},coords={x=0.306,y=0.772,source="quest_giver",zoneID=15355},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Lightbloom curbed"}},worldTaskTitle="Culling the Light"},
[86902] = {id=86902,name="Relinquishing Relics",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16215,mapID=2424,description="My staff bought us time in the effort to hold back the Void, but these relics will be a more powerful aid. Let us hope it will be enough. Quickly, deliver these relics to our friends.",objectivesText="Distribute relics to Taelia, Valunei , Salandria , and Mehlar. Progress: Did you get those relics out to everyone, <name>?",starts={{npcID=251355,x=0.526,y=0.558,zoneID=16215}},ends={{npcID=251355,x=0.526,y=0.558,zoneID=16215}},coords={x=0.526,y=0.558,source="quest_giver",zoneID=16215},questType="world",worldTaskTitle="Relinquishing Relics"},
[86903] = {id=86903,name="The Arcantina",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=10473,mapID=2541,description="$p, there's a place that we used during the Second War, when we missed our homes an' needed to remember Azeroth. Somethin' of a retreat an' a sanctuary for those who've seen too much fighting--too much pain. Over time, we've brought friends and allies there. In recent years, members o' the Horde have been invited as well. We call it the Arcantina. I believe Arator , and you, would benefit from some respite there. Use this key to make a portal.",objectivesText="Visit the Arcantina. Progress: This really is quite the place, isn't it, <name>?",starts={{npcID=253125,x=0.406,y=0.66,zoneID=15969}},ends={{npcID=237502,x=0.508,y=0.604,zoneID=10473}},coords={x=0.406,y=0.66,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="The Arcantina"},
[86909] = {id=86909,name="Unrestful Spirits",level=83,requiredLevel=83,faction="none",expansion=11,zoneID=15355,mapID=2413,questType="world",worldTaskTitle="Unrestful Spirits"},
[87759] = {id=87759,name="Encapsulated Void",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16648,mapID=2444,objectivesText="Subdue Void Creatures or Kill Players Subdue Void Creatures",questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Subdue Void Creatures or Kill Players"},{orderIndex=2,type=0,amount=10,objectID=239434,text="Subdue Void Creatures"}},worldTaskTitle="Encapsulated Void",db2QuestInfoID=113,db2QuestInfoName="PvP World Quest"},
