[89289] = {id=89289,name="Favor of the Court",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Ah, , my favorite ! I am delighted to see you in attendance once more. You have quite the natural talent for these sorts of affairs. The nobles are pleased with your presence and your favor has been swaying their coffers. Let us not stop a good thing, shall we? Help me choose an ally of our representatives to invite to the Haven this week. I'm ever curious to see the drama you will stir up. As my personal guest of honor, your favor will be seen as an extension of my favor.",objectivesText="Choose an ally of the Magisters, Blood Knights, Farstriders, or Shades of the Row to invite to Saltheril's Soiree this week. Your choice will determine which faction will offer \"Fortify the Runestones\" to your Warband this week. Progress: Be cautious, as always. The sin'dorei take great offense to many subtle things.",starts={{npcID=240832,x=0.426,y=0.472,zoneID=15968}},ends={{npcID=240832,x=0.426,y=0.472,zoneID=15968}},coords={x=0.426,y=0.472,source="quest_giver",zoneID=15968},questType="world",worldTaskTitle="Favor of the Court"},
[89347] = {id=89347,name="Overcoming the Unknown: Rage-Riddled Drifter",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15958,mapID=2444,objectivesText="Kill the Rage-Riddled Drifter",starts={{x=0.555,y=0.324,mapID=2444}},ends={{x=0.555,y=0.324,mapID=2444}},coords={mapID=2444,x=0.555,y=0.324},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=241472,text="Kill the Rage-Riddled Drifter"}},worldTaskTitle="Overcoming the Unknown: Rage-Riddled Drifter",db2QuestInfoID=278,db2QuestInfoName="PvP Elite World Quest"},
