[89441] = {id=89441,name="Clear the Decks",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16182,mapID=2432,objectivesText="Instruct Salandria to fall back",starts={{x=0.398,y=0.574,mapID=2432}},ends={{x=0.398,y=0.574,mapID=2432}},coords={mapID=2432,x=0.398,y=0.574},questType="world",db2Objectives={{orderIndex=2,type=0,amount=1,objectID=244062,text="Instruct Salandria to fall back"}},worldTaskTitle="Clear the Decks"},
[90467] = {id=90467,name="Tales of the Sky",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Wait a minute... You're no rutaani at all! Are you one of those \"outsiders\" that Saku and Orkon keep talking about? Oh! I just had a great idea. Did you know that the Goddess used to have a pet? Rumor has it that when the Goddess disappeared, Aln'sharan was SO sad that he flew up into the highest roots of Harandar , never to be seen again. But every so often, he goes looking for food... And his scales fall as skyglass! I wanna gather some. It's my dream to see Aln'sharan firsthand! Will you help me?",objectivesText="Collect 6 Stray Skyshards in the Cascades of Harandar . Progress: Aln'sharan is a folk tale that we tell haranir children to explain the shards of glass that occasionally rain upon Harandar . Most grow out of searching for sky serpents. But Kuri 's heart has always been filled with whimsy.",starts={{npcID=242358,x=0.662,y=0.254,zoneID=15355}},ends={{npcID=242689,x=0.694,y=0.292,zoneID=15355}},coords={x=0.662,y=0.254,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="Tales of the Sky"},
[90533] = {id=90533,name="Go Get Orweyna!",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Hey! Champ! Look, I swear I'm glad to see ya. I'm just in a little bit of a diplomatic situation here. Can you go get Orweyna and bring her back here? See if she'll talk this beast into letting me go? I'm not an elekk plushie, for cryin' out loud.",objectivesText="Go get Orweyna in the Den and find a way to free Gazlowe. Progress: Never try to take something from a beast like this without offering something better. I would hate to lose another friend that way.",starts={{npcID=242593,x=0.47,y=0.458,zoneID=15355}},ends={{npcID=242592,x=0.54,y=0.552,zoneID=15355}},coords={x=0.47,y=0.458,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="Go Get Orweyna!"},
[90733] = {id=90733,name="The Listener",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Now that you've learned about our legends, you've earned the notice of one of our elders. He wants to meet you. His name is Aksem , and he knows things that the rest of us have never learned. History that remains hidden, even in the paintings. Go and introduce yourself. He's expecting you.",objectivesText="Speak to Aksem in the Den.",starts={{npcID=238170,x=0.542,y=0.53,zoneID=15355}},ends={{npcID=243759,x=0.534,y=0.494,zoneID=15355}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="The Listener"},
[90734] = {id=90734,name="In the Name of the Goddess",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The high priest Aksem has asked for you again. He said you are not the only one on a quest for knowledge about the deep history of Harandar . Go to him. I believe he already has another guest who is also interested in learning this hidden history.",objectivesText="Return to Aksem in the Den. Progress: Tea will calm your thoughts.",starts={{npcID=238170,x=0.542,y=0.53,zoneID=15355}},ends={{npcID=243759,x=0.534,y=0.494,zoneID=15355}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="In the Name of the Goddess"},
[90741] = {id=90741,name="Once More Into the Rift",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Aksem has asked for you again. He says he's ready for you to undergo the final ritual for the knowledge he wants to teach you. I admit, I'm envious, but I do not envy the trials you'll need to undergo in order to prepare for this knowledge. Go speak to Aksem , and do as he says. Orweyna will be joining you.",objectivesText="Speak to Aksem , then meet Orweyna in the Rift of Aln.",starts={{npcID=238170,x=0.542,y=0.53,zoneID=15355}},ends={{npcID=243795,x=0.618,y=0.622,zoneID=15355}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="Once More Into the Rift"},
[90849] = {id=90849,name="Light Show",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16182,mapID=2432,objectivesText="Luminescent Wards activated",starts={{x=0.362,y=0.275,mapID=2432}},ends={{x=0.362,y=0.275,mapID=2432}},coords={mapID=2432,x=0.362,y=0.275},questType="world",db2Objectives={{orderIndex=1,type=0,amount=6,objectID=244520,text="Luminescent Wards activated"}},worldTaskTitle="Light Show"},
[90957] = {id=90957,name="Initiation Day",level=10,requiredLevel=10,faction="both",expansion=11,zoneID=15355,mapID=2413,description=", today is when you find your proper place among the haranir. Root Tender Dalnir will guide you. His path is one of tradition and humility, so don't expect excitement. By the end of the day, you will make your mark in the Den of Remembrance. The story you begin now will build on those that came before, like the roots themselves, growing the foundations of Harandar. Dalnir was clearing invasive drifters from the roots. Before you go to him, aid Dalnir by removing some of the pests yourself.",objectivesText="Elder Hagar is asking you to kill 6 Invasive drifters from around the roots of Teldrassil, and then meet with Root Tender Dalnir .",starts={{npcID=245090,x=0.348,y=0.25,zoneID=15355}},ends={{npcID=245102,x=0.352,y=0.234,zoneID=15355}},coords={x=0.348,y=0.25,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="Initiation Day"},
[90958] = {id=90958,name="Roots Above All",level=10,requiredLevel=10,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Some say the great trees grow, and Harandar will remain even if we do not tend them. Our traditions say, it does not matter. We remain here to protect, tend and serve. We do this with dedication and humility. Keeping the environment around the roots clean and free of pests reflects upon this duty. Return to me once you are done. You will represent our ways well, .",objectivesText="Root Tender Dalnir wants you to pull weeds, remove mud skippers and invasive fungi from the area. Progress: Have you performed the tasks that I have asked for?",starts={{npcID=245102,x=0.352,y=0.234,zoneID=15355}},ends={{npcID=245102,x=0.352,y=0.234,zoneID=15355}},coords={x=0.352,y=0.234,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="Roots Above All"},
[90959] = {id=90959,name="Traditional Duties",level=10,requiredLevel=10,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Dalnir has a point about the ceremony, but we should not focus too narrowly. I still hold the values of our people, but sometimes we must look beyond. Do not worry. You should be focusing on the ceremony. I will search for the outsiders later. I am sure you could join me once the initiation ceremony is done.",objectivesText="An inner voice is telling you to search for the outsider in Har'mara. Progress: Hello, <name>. Hagar offered that I will remain as a witness to your ceremony.",starts={{npcID=245879,x=0.352,y=0.234,zoneID=15355}},ends={{npcID=245881,x=0.34,y=0.268,zoneID=15355}},coords={x=0.352,y=0.234,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="Traditional Duties"},
[90960] = {id=90960,name="My Story, My Legacy",level=10,requiredLevel=10,faction="both",expansion=11,zoneID=15355,mapID=2413,description=", the final part of the ceremony is ahead of you, though you've put it at risk with your digressions. The first mural will show you a vision of your true self, the one that resonates from within you. The second mural will show you a vision of where you are needed. The third mural, tradition tells us, breaks the barrier between us and the Goddess herself. The ceremony will conclude with you painting your story in the Den.",objectivesText="Elder Hagar asked you to commune with the three murals, and then paint your own story. Progress: Take your time, <name>. The ceremony is not about how fast you do it, but about what you learn from it.",starts={{npcID=245096,x=0.34,y=0.268,zoneID=15355}},ends={{npcID=245097,x=0.318,y=0.274,zoneID=15355}},coords={x=0.34,y=0.268,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="My Story, My Legacy"},
