[91375] = {id=91375,name="The Silence at Fungara Village",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Fungara Village has been silent for some time now. We've largely been occupied with the Lightbloom and the threat it presents, so we haven't had time to check in on the fungarians to the east. Usually, they are rowdy yet manageable... but it's rare that they go completely silent. I am going to investigate. If you wish to prove yourself an ally, you would do well to join me.",objectivesText="Seek Ghikal outside of Fungara Village in Harandar .",starts={{npcID=257002,x=0.334,y=0.666,zoneID=15355}},ends={{npcID=246777,x=0.438,y=0.716,zoneID=15355}},coords={x=0.334,y=0.666,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="The Silence at Fungara Village"},
