[91627] = {id=91627,name="Saltheril's Haven",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description=", I presume? Very good. Your reputation precedes you. Lord Saltheril sends his most sincere greetings, along with a cordial invitation to join him at his estate south of Silvermoon. A portion of the grounds have been carved out as a decadent haven for those seeking refined company and pleasant conversation. He believes you would bring a... unique perspective. Receiving an invitation is a rare honor. His lordship hopes you will accept.",objectivesText="Speak to Lord Saltheril at Saltheril's Haven.",starts={{npcID=247955,x=0.456,y=0.626,zoneID=15969}},ends={{npcID=240832,x=0.426,y=0.472,zoneID=15968}},coords={x=0.456,y=0.626,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Saltheril's Haven"},
[91700] = {id=91700,name="Darkness Unmade",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="The Void energies concentrated in this citadel have given rise to numerous aberrant creatures. Wildlife mutated by residual energy and horrors originating from beyond the anomalies, continue to feed and draw upon the energies here. It is most unpleasant! To safeguard my future enterprises, these threats must be neutralized.",objectivesText="Eliminate 2 Rare creatures in the Stormarion Citadel and surrounding area. Progress: Have you eliminated the threats?",starts={{npcID=244749,x=0.264,y=0.676,zoneID=15458}},ends={{npcID=244749,x=0.264,y=0.676,zoneID=15458}},coords={x=0.264,y=0.676,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="Darkness Unmade",db2QuestInfoID=1,db2QuestInfoName="Group"},
[91785] = {id=91785,name="Ensporcelled",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15355,mapID=2413,objectivesText="Lightbloom Spores slain",starts={{x=0.411,y=0.66,mapID=2413}},ends={{x=0.411,y=0.66,mapID=2413}},coords={mapID=2413,x=0.411,y=0.66},questType="world",db2Objectives={{orderIndex=0,type=21,amount=20,objectID=5352,text="Lightbloom Spores slain"}},worldTaskTitle="Ensporcelled",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[91787] = {id=91787,name="The Journey Ends",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The Light takes many forms. But I know now what it means to me, and how I want to wield it. I'm not just a weapon like my father, nor can I devote myself purely to service like Dezco. But I can protect people from the evil that threatens them. Right now, that's Xal'atath and her Devouring Host. We should return to Lor'themar and do whatever is needed to defeat the Void. Beyond that, I shall see where protecting others with the Light takes me.",objectivesText="Return to Silvermoon.",starts={{npcID=237502,x=0.508,y=0.604,zoneID=10473}},ends={{npcID=235787,x=0.454,y=0.704,zoneID=15969}},coords={x=0.508,y=0.604,source="quest_giver",zoneID=10473},questType="world",worldTaskTitle="The Journey Ends"},
