[91928] = {id=91928,name="What's For Lunch?",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="My Shadowtrade Mercenaries will fight for Stormarion Cores , no questions asked, but they do get hungry also! Food is quite scarce here, so we need supplies! Take a mercenary out with you and find some food for them to eat. I'll make it worth your while!",objectivesText="Slay Trigores for 3 Trigore Flanks and collect 20 Shadow-Grown Berries that grow in the area. Progress: Is that mercenary well fed?",starts={{npcID=244749,x=0.264,y=0.676,zoneID=15458}},ends={{npcID=244749,x=0.264,y=0.676,zoneID=15458}},coords={x=0.264,y=0.676,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="What's For Lunch?"},
[91929] = {id=91929,name="What's For Lunch?",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="My Shadowtrade Mercenaries will fight for Stormarion Cores , no questions asked, but they do get hungry also! Food is quite scarce here, so we need supplies! Take a mercenary out with you and find some food for them to eat. I'll make it worth your while!",objectivesText="Slay Unstable Oozeling for 12 Void Malgrease and collect 3 Domanaar Microwell . Progress: Is that mercenary well fed?",starts={{npcID=244749,x=0.264,y=0.676,zoneID=15458}},ends={{npcID=244749,x=0.264,y=0.676,zoneID=15458}},coords={x=0.264,y=0.676,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="What's For Lunch?"},
[91930] = {id=91930,name="The Abundant Lands",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De loa have reunited with us forest trolls, and de land reacts with glorious bounty! Do ya wish to take part? Then go north, and meet me at de entrance to Loaknit Den. There I will introduce ya to prosperity and plentitude like ya never seen...",objectivesText="Speak with Chel the Chip at Loaknit Den in Zul'Aman.",starts={{npcID=241924,x=0.45,y=0.676,zoneID=15947}},ends={{npcID=241928,x=0.316,y=0.262,zoneID=15947}},coords={x=0.45,y=0.676,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="The Abundant Lands"},
[91932] = {id=91932,name="The Abundant Awakening",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De Loa of Abundance accepts everyone, and everyone de Loa of Abundance accepts is granted de privilege of learnin' how best to serve abundance. Speak with his glorious visage and become a fellow acolyte.",objectivesText="Speak with the Loa of Abundance and learn the ways of harvesting abundance. Progress: Do not fear. I am indeed the finest judge of your every action and choice.",starts={{npcID=241928,x=0.316,y=0.262,zoneID=15947}},ends={{npcID=251601,x=0.316,y=0.26,zoneID=15947}},coords={x=0.316,y=0.262,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="The Abundant Awakening"},
[91933] = {id=91933,name="The Abundant Honor",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,description="On to the next phase of your education: mercantilism! Imagine yourself, offering the bounty of endless harvest to my glorious self, and reaping the abundant rewards I bestow upon you in kind. Now let us put that beauteous vision into practice! I will grant you a minute portion of unalloyed abundance . You, in turn, shall trade it to your fellow acolyte for one of many premium goods.",objectivesText="Purchase an Abundant Beacon from Chel the Chip . Progress: There are few things amongst mortals or gods that cannot be viewed through the lens of trade. Some of us are simply... less coy about that truth than others are.",starts={{npcID=251601,x=0.316,y=0.26,zoneID=15947}},ends={{npcID=251601,x=0.316,y=0.26,zoneID=15947}},coords={x=0.316,y=0.26,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="The Abundant Honor"},
[91937] = {id=91937,name="Portraits in the Vale",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15355,mapID=2413,objectivesText="Ride Bo'ke Local Wildlife chronicled Common Rare Epic Legendary",starts={{x=0.634,y=0.496,mapID=2413}},ends={{x=0.634,y=0.496,mapID=2413}},coords={mapID=2413,x=0.634,y=0.496},questType="world",db2Objectives={{orderIndex=0,type=3,amount=1,objectID=249095,text="Ride Bo'ke"},{orderIndex=1,type=15,amount=1,objectID=0,text="Local Wildlife chronicled"},{orderIndex=2,type=0,amount=50,objectID=249089,text="Common"},{orderIndex=3,type=0,amount=25,objectID=249090,text="Rare"},{orderIndex=4,type=0,amount=14,objectID=249091,text="Epic"},{orderIndex=5,type=0,amount=9,objectID=249092,text="Legendary"}},worldTaskTitle="Portraits in the Vale",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[91970] = {id=91970,name="WANTED: Gelatonius",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Are you ready to test yourself against a true foe? In the center of the Gloom Mire is Gelatonius , a fungal giant of enormous proportions. Kill him, if you think you can. I'm willing to be impressed, and to pay handsomely for this task.",objectivesText="Kill Gelatonius in the Gloom Mire.",starts={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},ends={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},coords={x=0.518,y=0.742,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="WANTED: Gelatonius",db2QuestInfoID=1,db2QuestInfoName="Group"},
[91980] = {id=91980,name="WANTED: Hellebora's Thorn",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15355,mapID=2413,description="See that huge creature over that way? That's Hellebora. She's set herself up too close to the road and we're concerned she's going to wander out of the mire and become even more of a threat. Deal with her, if you can, and bring me back one of her thorns as proof of your hunt.",objectivesText="Kill Hellabora. Progress: Hurry up and put Hellebora down before she wanders out of the mire.",starts={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},ends={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},coords={x=0.518,y=0.742,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="WANTED: Hellebora's Thorn",db2QuestInfoID=1,db2QuestInfoName="Group"},
[91981] = {id=91981,name="To Poison and to Heal",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15355,mapID=2413,starts={{x=0.436,y=0.546,mapID=2413}},ends={{x=0.436,y=0.546,mapID=2413}},coords={mapID=2413,x=0.436,y=0.546},questType="world",worldTaskTitle="To Poison and to Heal",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[91982] = {id=91982,name="WANTED: Toadshade's Petals",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The three-headed hydra, Hellabora, has been causing havoc in the lower end of Gloom Mire. Give her a good pruning and bring me back her petals as proof.",objectivesText="Collect petals from Toadshade. Progress: Less talking, more pruning. Go get those petals.",starts={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},ends={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},coords={x=0.518,y=0.742,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="WANTED: Toadshade's Petals",db2QuestInfoID=1,db2QuestInfoName="Group"},
[91998] = {id=91998,name="WANTED: Muckmire's Choking Vines",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Deep within the swamp is a creature of mud, leaves, and rage. His vines choke the life out of any who come near, and this dangerous creature cannot be allowed to live. Defeat Muckmire and bring me back his vines as proof of the deed.",objectivesText="Collect the choking vines of Muckmire. Progress: Be careful Muckmire doesn't drag you into the mud with him.",starts={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},ends={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},coords={x=0.518,y=0.742,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="WANTED: Muckmire's Choking Vines",db2QuestInfoID=1,db2QuestInfoName="Group"},
[92012] = {id=92012,name="WANTED: Gorebarb's Pincers",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Gorebarb is a creature quite unlike most others who make Harandar their home. He's incredibly violent and his kind is not seen here very often. Let's see less of him. Kill him and bring me his pincers as proof of the deed.",objectivesText="Collect Gorebarb's Pincers . Progress: Take care that Gorebarb doesn't catch you with those pincers. I imagine his breath isn't pleasant at all.",starts={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},ends={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},coords={x=0.518,y=0.742,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="WANTED: Gorebarb's Pincers",db2QuestInfoID=1,db2QuestInfoName="Group"},
[92013] = {id=92013,name="WANTED: Dionaea's Thorntusks",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Many thornmaws make the mire their home, but none as are vicious as Dionaea. Unlike the others, she kills merely for the joy of it, and her gluttony threatens the delicate balance of the wildlife in this area. Take her out and restore the equilibrium. Bring me back her thorntusks as proof of the deed.",objectivesText="Collect Dionaea's thorntusks. Progress: Dionaea hunts for the thrill of it. She seems to be unable to satiate her hunger. Have you handled her yet?",starts={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},ends={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},coords={x=0.518,y=0.742,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="WANTED: Dionaea's Thorntusks",db2QuestInfoID=1,db2QuestInfoName="Group"},
