[92365] = {id=92365,name="Creating Defenses",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Deploying defenses is crucial to safeguarding operation of the Singularity Anchor. I need to ensure you fully understand the process. First, collect the Stormarion cores I have in storage. Then, activate the defensive positions, and finally, choose and deploy one defense at each position. When you have completed that I can entrust you with further Stormarion cores to use as you see fit.",objectivesText="Follow the steps and deploy two defenses. Progress: Have you deployed the defenses?",starts={{npcID=248114,x=0.268,y=0.68,zoneID=15458}},ends={{npcID=248114,x=0.268,y=0.68,zoneID=15458}},coords={x=0.268,y=0.68,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="Creating Defenses"},
[92407] = {id=92407,name="Hidey-Hole",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="When Xal'atath departed she left behind a large number of anomalies, small pocket dimensions where enemies can hide. As Romuul calls them, \" Hidey-Holes \". The Artificer has rigged up a device that should do the job. We need to close these Hidey-Holes and flush out any enemies lurking inside.",objectivesText="Use the Anomaly Inverter to collapse 5 Hidey-Holes . Progress: Have you removed the anomalies?",starts={{npcID=248114,x=0.268,y=0.68,zoneID=15458}},ends={{npcID=248114,x=0.268,y=0.68,zoneID=15458}},coords={x=0.268,y=0.68,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="Hidey-Hole"},
