[92555] = {id=92555,name="Honor the Flame",level=1,requiredLevel=1,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The time of Dawnsummer Festal has long been a cherished season for our people. Even during the years under the cold grasp of the Ghostlands, the people of Tranquillien strived to maintain this ancient celebration and bring a little light to these once-cold lands. Now, warmth yourself by the bonfire and honor the flames of summer!",starts={{npcID=252192,x=0.488,y=0.638,zoneID=15968}},ends={{npcID=569165,x=0.489,y=0.639,zoneID=15968}},coords={x=0.488,y=0.638,source="quest_giver",zoneID=15968},questType="world",worldTaskTitle="Honor the Flame"},
[92556] = {id=92556,name="Honor the Flame",level=1,requiredLevel=1,faction="both",expansion=11,zoneID=15969,mapID=2393,description="A joyous Midsummer and Dawnsummer Festal upon you, ! While celebrating around the bonfire, it is important to pause for a moment of reflection. Much has happened here in Silvermoon in recent times and while we cannot dwell upon the darkness of the past, we must look towards the rising Dawn. Take a moment, while you honor the bonfire, and reflect upon its warmth!",starts={{npcID=248989,x=0.486,y=0.808,zoneID=15969}},ends={{npcID=569162,x=0.486,y=0.811,zoneID=15969}},coords={x=0.486,y=0.808,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Honor the Flame"},
[92557] = {id=92557,name="Honor the Flame",level=1,requiredLevel=1,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Fetna Alai-nazdo is upon us once again! Although her trample may be dark, her flame burns brightly in all of us! May this turn of the Season burn bright and bring good fortune to you and all who celebrate Fetna Alai-nazdo!",starts={{npcID=248975,x=0.544,y=0.168,zoneID=15947}},ends={{npcID=569166,x=0.543,y=0.169,zoneID=15947}},coords={x=0.544,y=0.168,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Honor the Flame"},
[92558] = {id=92558,name="Honor the Flame",level=1,requiredLevel=1,faction="both",expansion=11,zoneID=15458,mapID=2405,description="I remember the Dawnsummer Festal celebrations back in Eversong and thought 'why not light my own bonfire here in the Howling Ridge?' Thankfully, the local denizens didn't need much convincing. I told them the bonfires were sacrificial wells for vessels of esoteric magic and... well, that's one way to describe midsummer blossoms, right? Will you take a moment and honor the voidflame?",starts={{npcID=252194,x=0.536,y=0.702,zoneID=15458}},ends={{npcID=569169,x=0.537,y=0.701,zoneID=15458}},coords={x=0.536,y=0.702,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="Honor the Flame"},
[92559] = {id=92559,name="Honor the Flame",level=1,requiredLevel=1,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The season of Midsummer may be unfamiliar to us, but telling stories by the glow of our root flames is not. Take a moment to reflect by the bonfire, friend, and listen to those around you. Ponder that which has come before you and that which has yet to unfurl.",starts={{npcID=252196,x=0.542,y=0.514,zoneID=15355}},ends={{npcID=569167,x=0.543,y=0.514,zoneID=15355}},coords={x=0.542,y=0.514,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="Honor the Flame"},
