[92945] = {id=92945,name="The Power of Anguish",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="These threats we chase are intelligent. Determined. Deadly. Their ingenuity will seek to confound you. Their strength will seek to destroy you. It is from their very will to live--to predate--that we will extract the essence required to fuel the magical defenses of our city. I have had my assistants lay out our friend's toys. You'd do best to familiarize yourself with them.",objectivesText="Learn how to hunt your prey. Progress: Speak with Astalor Bloodsworn to continue.",starts={{npcID=253513,x=0.428,y=0.104,zoneID=15968}},ends={{npcID=253513,x=0.428,y=0.104,zoneID=15968}},coords={x=0.428,y=0.104,source="quest_giver",zoneID=15968},questType="world",worldTaskTitle="The Power of Anguish"},
[92954] = {id=92954,name="Maisara Caverns: Master of Souls",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16395,mapID=2437,description="Malacrass's notes are with Vordaza, and she's using them to further her necromantic experiments. I need you to go into de Maisara Caverns to recover them. It will be dangerous, and you will need to gather allies before venturing in. I will stay here and protect my uncle. We need to sort through all de scrolls we gathered and see what else we can find out.",starts={{npcID=253806,x=0.444,y=0.366,zoneID=15947}},ends={{npcID=253806,x=0.444,y=0.366,zoneID=15947}},coords={x=0.444,y=0.366,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Maisara Caverns: Master of Souls",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
[93013] = {id=93013,name="Special Assignment: Push Back the Light",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15355,mapID=2413,objectivesText="Ride the Haranir Petalwing Lightbloom rutaani defeated",starts={{x=0.327,y=0.774,mapID=2413}},ends={{x=0.327,y=0.774,mapID=2413}},coords={mapID=2413,x=0.327,y=0.774},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=241799,text="Ride the Haranir Petalwing"},{orderIndex=1,type=15,amount=1,objectID=0,text="Lightbloom rutaani defeated"}},worldTaskTitle="Special Assignment: Push Back the Light",db2QuestInfoID=286,db2QuestInfoName="Capstone World Quest"},
[93046] = {id=93046,name="Nestled Belongings",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15355,mapID=2413,objectivesText="Orweyna's Belongings found",starts={{x=0.313,y=0.855,mapID=2413}},ends={{x=0.313,y=0.855,mapID=2413}},coords={mapID=2413,x=0.313,y=0.855},questType="world",db2Objectives={{orderIndex=0,type=0,amount=4,objectID=253808,text="Orweyna's Belongings found"}},worldTaskTitle="Nestled Belongings",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93047] = {id=93047,name="Butchery Basics",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="We can't keep up with how much these soldiers eat. Lend us just a bit of your time to feed dis army, hm? We need boar. Not just a steak or two, we need de entire boar. Nothin' goes to waste, yah?",objectivesText="Collect 10 Boar Carcasses . Progress: De art of Amani huntin' is about discipline. You practice until de skills come as naturally as breathin'. But right now, discipline means doin' what I tell you.",starts={{npcID=241072,x=0.454,y=0.694,zoneID=15947}},ends={{npcID=241072,x=0.454,y=0.694,zoneID=15947}},coords={x=0.454,y=0.694,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Butchery Basics"},
[93048] = {id=93048,name="Got No Rhythm",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Dat boy Kovu stormed out of here without even tryin' a single step. He thinks he's got two left feet, but he isn't even willin' to try. You look like an impressive fighter. He'll respect you for dat. Maybe he just needs de right dance partner to show him de steps. Help him out, hm?",objectivesText="Teach Kovu how to dance. Progress: Makin' progress, yah?",starts={{npcID=254142,x=0.468,y=0.662,zoneID=15947}},ends={{npcID=254142,x=0.468,y=0.662,zoneID=15947}},coords={x=0.468,y=0.662,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Got No Rhythm"},
[93049] = {id=93049,name="Homework Support",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="My friends are goin' out to play down where de shade lilies grow, but I'm supposed to do a buncha borin' apothecary stuff. Papa wants me to collect some plants to make salves and balms we use for healin'. I asked if it could wait and he said no. What if... you helped me out? Just dis once, pleeease?",objectivesText="Collect 15 Pristine Shade Lilies and 8 Dragonhawk Fern Fronds . Progress: Did you get all of dem?",starts={{npcID=254144,x=0.466,y=0.68,zoneID=15947}},ends={{npcID=254144,x=0.466,y=0.68,zoneID=15947}},coords={x=0.466,y=0.68,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Homework Support"},
[93050] = {id=93050,name="Altar History",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De altars need to be infused with de power of de loas every so often. I'm not as spry as I used to be and de altars are all spread out. Help an old shaman out, eh? I'll give you my totem to channel de loas' power into de altars. And maybe you can learn a thing or two from de other acolytes and myself in de process.",objectivesText="Empower the 4 Loa Altars. Progress: I just need to take a little breather here. Don't go worryin' about me, now. Keep focused on the task at hand, eh?",starts={{npcID=254146,x=0.434,y=0.688,zoneID=15947}},ends={{npcID=257797,x=0.434,y=0.688,zoneID=15947}},coords={x=0.434,y=0.688,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Altar History"},
[93051] = {id=93051,name="The Final Exam",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="My trainin' is almost complete! My commander says I need to prove myself against a strong fighter before she can recommend me for combat. But I've been strugglin' to find someone willin' to spar with me after... uh, after what happened de last time... You look capable. And intimidatin'. Mind helpin' me out here? And no goin' easy on me, yes? I can take it.",objectivesText="Spar Dar'rak for his final exam. Progress: Do not pull even a single punch. De boy must succeed or fail on his own. If he's not ready, you will be doin' him no favors sendin' him into the fray unprepared.",starts={{npcID=255406,x=0.432,y=0.67,zoneID=15947}},ends={{npcID=255907,x=0.438,y=0.646,zoneID=15947}},coords={x=0.432,y=0.67,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="The Final Exam"},
