[93397] = {id=93397,name="Gnawing Hunger",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15458,mapID=2405,objectivesText="Gather carrion to weaken Slavering Ultradons",starts={{x=0.577,y=0.727,mapID=2405}},ends={{x=0.577,y=0.727,mapID=2405}},coords={mapID=2405,x=0.577,y=0.727},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=254754,text="Gather carrion to weaken Slavering Ultradons"}},worldTaskTitle="Gnawing Hunger",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93423] = {id=93423,name="Sparks of War: Eversong Woods",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Mysterious creatures are out in the wild across the Eversong Woods . Go and see what you can find out about them.",objectivesText="Collect 100 Sparks of War in Eversong Woods , while in War Mode. Progress: There's still more to do.",starts={{npcID=254971,x=0.362,y=0.81,zoneID=15969}},ends={{npcID=254971,x=0.362,y=0.81,zoneID=15969}},coords={x=0.362,y=0.81,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Sparks of War: Eversong Woods"},
[93424] = {id=93424,name="Sparks of War: Zul'Aman",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="There's unknown danger out in Zul'Aman . Get out there and clear things up!",objectivesText="Collect 100 Sparks of War in Zul'Aman , while in War Mode. Progress: Well, get on then!",starts={{npcID=254971,x=0.362,y=0.81,zoneID=15969}},ends={{npcID=254971,x=0.362,y=0.81,zoneID=15969}},coords={x=0.362,y=0.81,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Sparks of War: Zul'Aman"},
[93425] = {id=93425,name="Sparks of War: Harandar",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Powerful creatures have grown through the lands across Harandar . Go look into it.",objectivesText="Collect 100 Sparks of War in Harandar , while in War Mode. Progress: There's more to explore.",starts={{npcID=254971,x=0.362,y=0.81,zoneID=15969}},ends={{npcID=254971,x=0.362,y=0.81,zoneID=15969}},coords={x=0.362,y=0.81,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Sparks of War: Harandar"},
[93426] = {id=93426,name="Sparks of War: Voidstorm",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Chaotic forces are being disruptive in the Voidstorm . Go investigate and clear things up!",objectivesText="Collect 100 Sparks of War in Voidstorm , while in War Mode. Progress: There's more to look out for.",starts={{npcID=254971,x=0.362,y=0.81,zoneID=15969}},ends={{npcID=254971,x=0.362,y=0.81,zoneID=15969}},coords={x=0.362,y=0.81,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Sparks of War: Voidstorm"},
[93432] = {id=93432,name="Swords to Plowshares",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="First Mor'duun and the Blade ambush Atal'Aman. Now it's overrun by these \"echoes...\" At least, that's what Doru calls them: echoes. All I see are ghosts of a bloodier time. And like those days, no matter how many we cut through, they never stop swarming in. Get out there and see for yourself. Bring de echoes' remains as well. Doru wants to study what dey are and how dey work.",objectivesText="Collect 20 Raider Ash Remains . Progress: It's like a dream you can't wake from.",starts={{npcID=254783,x=0.454,y=0.45,zoneID=16194}},ends={{npcID=254783,x=0.454,y=0.45,zoneID=16194}},coords={x=0.454,y=0.45,source="quest_giver",zoneID=16194},questType="world",worldTaskTitle="Swords to Plowshares"},
[93433] = {id=93433,name="Shrine, Sealed, Delivered",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="Curse de echoes. Curse Zul'jin, and Mor'duun, and dat snake Malacrass too. They only cause more mess for de livin' to clean up. Listen, hash'ura. I need you to deliver supplies to each of de shrines in de city. We've packaged food, water, bandages, and reagents to keep their barriers at full strength. Ask about their status as well. Though safe, they all likely feel boxed in.",objectivesText="Deliver supplies to the Elders of the four Loa Shrines: Elder Shimarra, Eagletender Rhyd, Elder Thak, and Elder Vu'lona.",starts={{npcID=254827,x=0.452,y=0.45,zoneID=16194}},ends={{npcID=254827,x=0.452,y=0.45,zoneID=16194}},coords={x=0.452,y=0.45,source="quest_giver",zoneID=16194},questType="world",worldTaskTitle="Shrine, Sealed, Delivered"},
[93435] = {id=93435,name="Four Instigators",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="De scouts report seein' a few unique faces among de echoes. I felt old angers rising when I heard de names. Dey were not honorable fighters for us to challenge ourselves against, such as yourself. They were vermin--greedy opportunists that drove legions of connivin' adventurers to rob us of our possessions, our treasures, and... our tusks. Slayin' de echoes of these key figures should reduce de number of echoes appearin'. And it will make me grin to know they've fallen.",objectivesText="Slay the echoes of Prigmon , Zungam , Budd Nedreck , and Harrison Jones .",starts={{npcID=254783,x=0.454,y=0.45,zoneID=16194}},ends={{npcID=254783,x=0.454,y=0.45,zoneID=16194}},coords={x=0.454,y=0.45,source="quest_giver",zoneID=16194},questType="world",worldTaskTitle="Four Instigators"},
[93436] = {id=93436,name="Hex the Innocent, Disrupt the Guilty",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="I will study de ashes you acquired, but we can get dis situation under control by means other than de axe. You must disrupt de battlefield, hash'ura. De echoes believe dey're in de midst of a decades-old battle, so we must target de support dey relied on back then. Poison de feasts dey find respite at, hex their disrespectful civilian allies, and sabotage dat chest they seem so keen on lootin'!",objectivesText="Poison 3 Raider's Feasts, hex 7 Civilians, and sabotage the Warlord's Chest. Progress: Let us prove dat even echoes of de past can feel woe.",starts={{npcID=254827,x=0.452,y=0.45,zoneID=16194}},ends={{npcID=254827,x=0.452,y=0.45,zoneID=16194}},coords={x=0.452,y=0.45,source="quest_giver",zoneID=16194},questType="world",worldTaskTitle="Hex the Innocent, Disrupt the Guilty"},
[93437] = {id=93437,name="In Their Own Blood",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2536,description="After studying de ashes, Doru believes we can only fight with de past using weapons of de past. I cannot ask this of any Amani. Or Witherbark, Revantusk, or Shadowpine. Ya presence with us in these times must be fate... because we could only make this request to an outsider. Ya must inhabit a soul of de profane ones: those that accepted Malacrass's vile bargain and consumed loa power during de era of Zul'jin. Return to de shrine of de profane one ya wish to merge with. Ancestors forgive us...",objectivesText="Become one of the four Loa Avatars. Slay Raiding Echoes in Atal'Aman, and defeat the Raid Leader upon the Warlord's Stair.",starts={{npcID=254783,x=0.454,y=0.45,zoneID=16194}},ends={{npcID=254783,x=0.454,y=0.45,zoneID=16194}},coords={x=0.454,y=0.45,source="quest_giver",zoneID=16194},questType="world",worldTaskTitle="In Their Own Blood"},
[93438] = {id=93438,name="Special Assignment: Precision Excision",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16648,mapID=2405,objectivesText="Ride the War-Wyrm Forces slain in lower courtyard Forces slain in lower courtyard HIDDEN Forces slain in upper courtyard Forces slain in upper courtyard HIDDEN High value targets eliminated Forces slain in Stormarion Watch Forces slain in Stormarion Watch HIDDEN Stormarion Supplies destroyed",starts={{x=0.358,y=0.704,mapID=2405}},ends={{x=0.358,y=0.704,mapID=2405}},coords={mapID=2405,x=0.358,y=0.704},questType="world",db2Objectives={{orderIndex=2,type=0,amount=99,objectID=255730,text="Forces slain in lower courtyard HIDDEN"},{orderIndex=4,type=0,amount=99,objectID=255740,text="Forces slain in upper courtyard HIDDEN"},{orderIndex=5,type=0,amount=5,objectID=255735,text="High value targets eliminated"},{orderIndex=7,type=0,amount=99,objectID=255788,text="Forces slain in Stormarion Watch HIDDEN"},{orderIndex=8,type=0,amount=5,objectID=255793,text="Stormarion Supplies destroyed"},{orderIndex=0,type=0,amount=1,objectID=255628,text="Ride the War-Wyrm"},{orderIndex=1,type=0,amount=10,objectID=255730,text="Forces slain in lower courtyard"},{orderIndex=3,type=0,amount=10,objectID=255740,text="Forces slain in upper courtyard"},{orderIndex=6,type=0,amount=7,objectID=255788,text="Forces slain in Stormarion Watch"}},worldTaskTitle="Special Assignment: Precision Excision",db2QuestInfoID=286,db2QuestInfoName="Capstone World Quest"},
[93440] = {id=93440,name="Personal History",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="With Mor'duun slain and de Twilight's Blade defeated, my people want to return to Atal'Aman. It should be a moment of great celebration but... somethin' unexpected is barrin' our way. Seek out Torundo and Elder Doru. Dey are supportin' de resettlement. They'll know how best to use your talents. Prepare yourself, hash'ura, and do not hesitate to defend Atal'Aman no matter who you meet there.",objectivesText="Speak with Torundo the Grizzled in Atal'Aman.",starts={{npcID=249653,x=0.456,y=0.654,zoneID=15947}},ends={{npcID=254783,x=0.454,y=0.45,zoneID=16194}},coords={x=0.456,y=0.654,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Personal History"},
[93501] = {id=93501,name="The Season Starts: Midnight",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Things have started to get interesting, . I'm hearing of all sorts of treasures popping up in delves. I'm compiling my notes in this book, and our illustrious hosts have even broken out some of their own artifacts to trade for what we uncover. Why don't you take a look before we head out. Better prepared than dead.",objectivesText="Review the Delver's Guide and the rewards offered by Naleidea Rivergleam and Telemancer Astrandis . Progress: Ready to get going?",starts={{npcID=242381,x=0.524,y=0.78,zoneID=15969}},ends={{npcID=242381,x=0.524,y=0.78,zoneID=15969}},coords={x=0.524,y=0.78,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="The Season Starts: Midnight"},
[93507] = {id=93507,name="Disrupting the Void",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15458,mapID=2405,objectivesText="Shadowguard operation disrupted Obtuse Joint 0.9 Obtuse Joint 1.1 Straight 0.6",starts={{x=0.388,y=0.451,mapID=2405}},ends={{x=0.388,y=0.451,mapID=2405}},coords={mapID=2405,x=0.388,y=0.451},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Shadowguard operation disrupted"},{orderIndex=4,type=2,amount=13,objectID=543716,text="Obtuse Joint 0.9"},{orderIndex=5,type=2,amount=13,objectID=543427,text="Obtuse Joint 1.1"},{orderIndex=6,type=2,amount=13,objectID=548730,text="Straight 0.6"}},worldTaskTitle="Disrupting the Void",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93511] = {id=93511,name="A Missing Member",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="He took him! Finley...big...purple...man!",objectivesText="Listen to what Reno has to say. Progress: He looks devastated.",starts={{npcID=255103,x=0.524,y=0.782,zoneID=15969}},ends={{npcID=242381,x=0.524,y=0.78,zoneID=15969}},coords={x=0.524,y=0.782,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="A Missing Member"},
