[93524] = {id=93524,name="Trench Run",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15458,mapID=2405,objectivesText="Knock down Voracious Harrower",starts={{x=0.512,y=0.672,mapID=2405}},ends={{x=0.512,y=0.672,mapID=2405}},coords={mapID=2405,x=0.512,y=0.672},questType="world",db2Objectives={{orderIndex=0,type=0,amount=20,objectID=255212,text="Knock down Voracious Harrower"}},worldTaskTitle="Trench Run",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93525] = {id=93525,name="Nulling Nullaeus",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="That thing looked tough, and it took Reno out as an afterthought. We'll want the best gear we can get before trying to take it down. Thankfully, I have some leads on bountiful delves we can start with.",objectivesText="Improve your gear until you are able to confront Nullaeus within his lair. Progress: He'll get what's coming to him.",starts={{npcID=242381,x=0.524,y=0.78,zoneID=15969}},ends={{npcID=242381,x=0.524,y=0.78,zoneID=15969}},coords={x=0.524,y=0.78,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Nulling Nullaeus"},
[93571] = {id=93571,name="Dispersing Shadows",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15458,mapID=2405,objectivesText="Void-Gorged monstrosities slain",starts={{x=0.31,y=0.5341,mapID=2405}},ends={{x=0.31,y=0.5341,mapID=2405}},coords={mapID=2405,x=0.31,y=0.5341},questType="world",db2Objectives={{orderIndex=0,type=0,amount=3,objectID=257920,text="Void-Gorged monstrosities slain"}},worldTaskTitle="Dispersing Shadows",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93573] = {id=93573,name="Deciphering Darkness",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16648,mapID=2405,objectivesText="Dark Vessel deciphered",starts={{x=0.418,y=0.753,mapID=2405}},ends={{x=0.418,y=0.753,mapID=2405}},coords={mapID=2405,x=0.418,y=0.753},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=256161,text="Dark Vessel deciphered"}},worldTaskTitle="Deciphering Darkness",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93575] = {id=93575,name="Maisara Caverns: Maisara Hungers",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16395,mapID=2437,description="I will not leave my people to die to de Vilebranch's dark rituals. We must go after dem. The heart of Maisara Caverns is where de Vilebranch keep their secrets. I expect dis to be a bloody trip. We will have to face de ugliness of the Vilebranch greed, and what it is costin' all of us. We must discover what purpose they have for my stolen kin. If any still be alive. I will be dere to aid you... but bring a fierce party of warriors. We will need it.",objectivesText="Complete the Maisara Caverns dungeon. Progress: Gather your warparty. I will see you in Maisara Caverns.",starts={{npcID=244521,x=0.44,y=0.344,zoneID=15947}},ends={{npcID=244521,x=0.44,y=0.344,zoneID=15947}},coords={x=0.44,y=0.344,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Maisara Caverns: Maisara Hungers",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
[93577] = {id=93577,name="Captured Instinct",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16648,mapID=2405,objectivesText="Ride the Cataloger's Disc Take Pictures of Wildlife Common Rare Epic Legendary",starts={{x=0.365,y=0.491,mapID=2405}},ends={{x=0.365,y=0.491,mapID=2405}},coords={mapID=2405,x=0.365,y=0.491},questType="world",db2Objectives={{orderIndex=0,type=3,amount=1,objectID=255543,text="Ride the Cataloger's Disc"},{orderIndex=1,type=15,amount=1,objectID=0,text="Take Pictures of Wildlife"},{orderIndex=2,type=0,amount=34,objectID=255539,text="Common"},{orderIndex=3,type=0,amount=20,objectID=255540,text="Rare"},{orderIndex=4,type=0,amount=13,objectID=255541,text="Epic"},{orderIndex=5,type=0,amount=9,objectID=255542,text="Legendary"}},worldTaskTitle="Captured Instinct",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93578] = {id=93578,name="Where Shadows Gather",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15958,mapID=2444,objectivesText="Disrupt the battlefield combatants T0 Kill T1 Kill T2 Kill Shatter Spear Shatter Sword Void Gate",starts={{x=0.44,y=0.75,mapID=2444}},ends={{x=0.44,y=0.75,mapID=2444}},coords={mapID=2444,x=0.44,y=0.75},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Disrupt the battlefield combatants"},{orderIndex=1,type=21,amount=34,objectID=5850,text="T0 Kill"},{orderIndex=2,type=21,amount=15,objectID=5851,text="T1 Kill"},{orderIndex=3,type=21,amount=10,objectID=5852,text="T2 Kill"},{orderIndex=4,type=2,amount=15,objectID=616568,text="Shatter Spear"},{orderIndex=5,type=2,amount=15,objectID=616570,text="Shatter Sword"},{orderIndex=6,type=2,amount=9,objectID=616575,text="Void Gate"}},worldTaskTitle="Where Shadows Gather",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93579] = {id=93579,name="Path of Purgation",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16648,mapID=2405,objectivesText="Slay enemies to gather Void Essence Fallow Altars empowered with Void Essence Altar 01 Altar 02 Altar 03 Altar 04",starts={{x=0.308,y=0.473,mapID=2405}},ends={{x=0.308,y=0.473,mapID=2405}},coords={mapID=2405,x=0.308,y=0.473},questType="world",db2Objectives={{orderIndex=1,type=0,amount=3,objectID=255672,text="Fallow Altars empowered with Void Essence"},{orderIndex=2,type=0,amount=1,objectID=255673,text="Altar 01"},{orderIndex=3,type=0,amount=1,objectID=255674,text="Altar 02"},{orderIndex=4,type=0,amount=1,objectID=255675,text="Altar 03"},{orderIndex=5,type=0,amount=1,objectID=255676,text="Altar 04"},{orderIndex=0,type=14,amount=1,objectID=219223,text="Slay enemies to gather Void Essence"}},worldTaskTitle="Path of Purgation",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93593] = {id=93593,name="A Call to Battle",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Ours is a world of constant struggle, wouldn't you agree? Even in between times of peace, there is value in keeping one's battle skills sharpened. I have heard much of your prowess. Let us see what you are capable of.",objectivesText="Win 4 Battleground matches. Progress: There is no substitute for constant vigilance, <class>. Al'anna, dalomore.",starts={{npcID=256212,x=0.488,y=0.646,zoneID=15969}},ends={{npcID=256212,x=0.488,y=0.646,zoneID=15969}},coords={x=0.488,y=0.646,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="A Call to Battle"},
[93595] = {id=93595,name="A Call to Delves",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Seeking out challenge and treasure can test one's skills, all while uncovering that which will give us even greater power. Were I you, I would delve into places that provide both.",objectivesText="Complete 5 Midnight Delves. Progress: Has your delving come to a satisfactory conclusion?",starts={{npcID=256212,x=0.488,y=0.646,zoneID=15969}},ends={{npcID=256212,x=0.488,y=0.646,zoneID=15969}},coords={x=0.488,y=0.646,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="A Call to Delves"},
[93598] = {id=93598,name="Emissary of War",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="It is only when we push ourselves beyond our limits that we truly grow... or fail and make way for others. Prove yourself by challenging the deadliest of places. Shorel'aran.",objectivesText="Complete 4 dungeons on Mythic difficulty. Progress: Will you become the stuff of myths and legends, <class>?",starts={{npcID=256212,x=0.488,y=0.646,zoneID=15969}},ends={{npcID=256212,x=0.488,y=0.646,zoneID=15969}},coords={x=0.488,y=0.646,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Emissary of War",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
[93599] = {id=93599,name="The Very Best",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Even the smallest amongst us must play their part. That includes our little friends. If you would strengthen both their prowess and your bond, challenge others. Only the fittest will survive.",objectivesText="Defeat 5 players through Find Battle with a team of level 25 pets. Progress: By strengthening those bonds, you and your little companions will be ready for whatever comes.",starts={{npcID=256212,x=0.488,y=0.646,zoneID=15969}},ends={{npcID=256212,x=0.488,y=0.646,zoneID=15969}},coords={x=0.488,y=0.646,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="The Very Best"},
[93600] = {id=93600,name="The Arena Calls",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Old, musty dungeons and battlefields are one thing, but the arena is where the wheat and the chaff are separated. Can you prove yourself, ? Show me. Let me hear your name shouted from the stands by those crying for blood.",objectivesText="Win 10 Arena Skirmish battles.",starts={{npcID=256212,x=0.488,y=0.646,zoneID=15969}},ends={{npcID=256212,x=0.488,y=0.646,zoneID=15969}},coords={x=0.488,y=0.646,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="The Arena Calls"},
[93605] = {id=93605,name="The World Awaits",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Sinu a'manore, . It is true in the past, I have been less than... egalitarian in my outlook. Yet in these times of trouble, there is much to be done--whether here in Quel'Thalas or elsewhere. Will you face the challenge and prove yourself once more?",objectivesText="Complete 10 Midnight World Quests.",starts={{npcID=256212,x=0.488,y=0.646,zoneID=15969}},ends={{npcID=256212,x=0.488,y=0.646,zoneID=15969}},coords={x=0.488,y=0.646,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="The World Awaits"},
[93648] = {id=93648,name="Gnarly Skullduggery",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,mapID=2512,questType="world",worldTaskTitle="Gnarly Skullduggery",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93649] = {id=93649,name="Got the Gall",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,mapID=2512,starts={{x=0.294,y=0.504,mapID=2512}},ends={{x=0.294,y=0.504,mapID=2512}},coords={mapID=2512,x=0.294,y=0.504},questType="world",db2Objectives={{orderIndex=1,type=1,amount=3,objectID=269918,text="Venom-Corroded Gallstone"}},worldTaskTitle="Got the Gall",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93651] = {id=93651,name="The Blinding Vale: Lightbloom Roots",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2393,description="We have traced Ruia's flight through the Rootways. As we suspected, he has sought refuge deep within The Blinding Vale, where the Lightbloom first took root within Harandar. With Alndust empowering our command of life, we are able to keep the Lightbloom from spreading uncontrolled. But we will run out of Alndust long before Ruia runs out of patience. Ruia is wise and powerful. But his actions in Eversong prove that his conviction has grown into an uncontrollable fanaticism. He must be stopped.",objectivesText="Complete The Blinding Vale dungeon. Progress: Ruia is too powerful to challenge alone. Who knows what manner of overgrown monsters lurk in the heart of the Lightbloom?",starts={{npcID=255822,x=0.366,y=0.686,zoneID=15969},{npcID=255828,x=0.508,y=0.53,zoneID=15355}},ends={{npcID=255828,x=0.508,y=0.53,zoneID=15355}},coords={x=0.366,y=0.686,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="The Blinding Vale: Lightbloom Roots",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
