[93744] = {id=93744,name="Unity Against the Void",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2393,starts={{x=0.49,y=0.646,mapID=2393}},ends={{x=0.49,y=0.646,mapID=2393}},coords={mapID=2393,x=0.49,y=0.646},questType="world",worldTaskTitle="Unity Against the Void",db2QuestInfoID=284,db2QuestInfoName="Meta Quest"},
[93751] = {id=93751,name="Windrunner Spire",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Former home of the Windrunners... now desecrated beyond thought. Since the Scourge invasion, the spire houses our greatest nightmares: banshees, abominations, hateful spirits. There is no redeeming such a place, but perhaps we may help lay the tormented to rest.",objectivesText="Complete the Windrunner Spire dungeon on any difficulty.",starts={{npcID=256210,x=0.49,y=0.648,zoneID=15969}},ends={{npcID=256210,x=0.49,y=0.648,zoneID=15969}},coords={x=0.49,y=0.648,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Windrunner Spire",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
[93752] = {id=93752,name="Murder Row",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="I've always disagreed with Lor'themar about the existence of Murder Row. But I guess like any forest, a city should and will have its secrets. Though recently, Lor'themar has expressed concern about rising fel activity in the area. With the majority of Silvermoon's watch on the Voidstorm, many folks are testing boundaries, taking advantage, making a play for power... You have my permission to investigate and crush any such illegal activities.",objectivesText="Complete the Murder Row dungeon on any difficulty. Progress: More reports of fel activity come in daily. Silvermoon is at risk, I fear. I hope you're on the case..",starts={{npcID=256210,x=0.49,y=0.648,zoneID=15969}},ends={{npcID=256210,x=0.49,y=0.648,zoneID=15969}},coords={x=0.49,y=0.648,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Murder Row",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
[93753] = {id=93753,name="Magisters' Terrace",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Powerful monsters of the void have taken over Magister's Terrace! These halls contain untold amounts of knowledge and arcane power. We cannot lose any of it to our enemy. Clear the voidspawns and their masters. You'll likely have to solve the terrace's defenses as well, which are designed to prevent and shutdown unauthorized access at any cost.",objectivesText="Complete the Magisters' Terrace dungeon on any difficulty. Progress: If the Void gains access to Silvermoon's most exclusive repository of magic... Rommath will throw a fit of epic proportions.",starts={{npcID=256210,x=0.49,y=0.648,zoneID=15969}},ends={{npcID=256210,x=0.49,y=0.648,zoneID=15969}},coords={x=0.49,y=0.648,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Magisters' Terrace",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
[93754] = {id=93754,name="Maisara Caverns",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="While Lady Liadrin was in Zul'Aman, she took note of one tribe, the Vilebranch, brutalizing the other forest trolls and their loa. They live up to their name by wanton use of necromancy. Enter their caverns and put a stop to their black magic!",objectivesText="Complete the Maisara Caverns dungeon on any difficulty. Progress: The Vilebranch usage of magic reeks of undead teachings... and I know that never ends well.",starts={{npcID=256210,x=0.49,y=0.648,zoneID=15969}},ends={{npcID=256210,x=0.49,y=0.648,zoneID=15969}},coords={x=0.49,y=0.648,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Maisara Caverns",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
[93755] = {id=93755,name="Den of Nalorakk",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="A trial of skill and strength... I'd go myself if I wasn't needed in Silvermoon. Good luck, champion. I look forward to hearing about your victory against the Amani Loa of War.",objectivesText="Complete the Den of Nalorakk dungeon on any difficulty. Progress: Didn't chicken out, did you? It's okay, your fear is not unfounded. Bears are the kings of nature. They'll mess you up.",starts={{npcID=256210,x=0.49,y=0.648,zoneID=15969}},ends={{npcID=256210,x=0.49,y=0.648,zoneID=15969}},coords={x=0.49,y=0.648,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Den of Nalorakk",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
[93756] = {id=93756,name="The Blinding Vale",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="This place in Harandar is the Lightbloom's epicenter. Orweyna did what she could, which was much, but we must strike at the taproot of all roots for the plant to die. Be on your guard, even if you think yourself experienced with the Lightbloom by now. The vale is different from the rampant, but ultimately wild growth in Eversong. It's a calculated force of nature led by a Rootwarden who seeks to strangle you and everything else it desires.",objectivesText="Complete The Blinding Vale dungeon on any difficulty. Progress: Learn what you can from the Lightbloom in Eversong, but beware this may be an entirely different set of problems. The Rootwarden will be expecting intruders such as yourself.",starts={{npcID=256210,x=0.49,y=0.648,zoneID=15969}},ends={{npcID=256210,x=0.49,y=0.648,zoneID=15969}},coords={x=0.49,y=0.648,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="The Blinding Vale",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
[93757] = {id=93757,name="Voidscar Arena",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="If I didn't know that the domanaar thirst for battle, and all the pain and strife that comes with it, I'd say this is trap. Either way, I suppose it's an invitation to get yourself killed. If you insist on participating in the Void's fighting games, I can't stop you. Just don't hesitate to kill as many voidspawn as possible while you're there, okay?",objectivesText="Complete the Voidscar Arena dungeon on any difficulty. Progress: May your arrows strike true, champion.",starts={{npcID=256210,x=0.49,y=0.648,zoneID=15969}},ends={{npcID=256210,x=0.49,y=0.648,zoneID=15969}},coords={x=0.49,y=0.648,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Voidscar Arena",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
[93758] = {id=93758,name="Nexus-Point Xenas",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="We must continue to keep an eye on this overpowered facility. If breached, disaster will spread beyond the Voidstorm. Unfortunately this magical and mechanical complex is beyond my area of expertise. Prepare yourself, and ensure that the Nexus-Point Xenas remains dormant.",objectivesText="Complete the Nexus-Point Xenas dungeon on any difficulty. Progress: If the Nexus-Point is overloaded, it'll be a very quick death for many. Let's not entertain that thought any further. Secure the facility!",starts={{npcID=256210,x=0.49,y=0.648,zoneID=15969}},ends={{npcID=256210,x=0.49,y=0.648,zoneID=15969}},coords={x=0.49,y=0.648,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Nexus-Point Xenas",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
[93792] = {id=93792,name="Blessings of the Loa",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="My name is Du'gal . And you are hash'ura. Kinduru has ordered me to train you in de ways of loa worship. Take honor in it. Very few gokinye have earned de right as you have. Beside me is de Altar of Blessings. You may use it to worship any of our loa, and you shall receive a sliver of power in thanks. Go ahead now, if ya be so kind.",objectivesText="Worship at the Altar of Blessings. Gain a blessing by choosing to combine the power of Akil'zon, Halazzi, Jan'alai, or Nalorakk with that of any lesser loa you've formed a bond with. Progress: De loa are quite generous indeed.",starts={{npcID=256510,x=0.43,y=0.692,zoneID=15947}},ends={{npcID=256510,x=0.43,y=0.692,zoneID=15947}},coords={x=0.43,y=0.692,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Blessings of the Loa"},
[93850] = {id=93850,name="Windrunner Spire: Haunting Melodies",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15808,mapID=2395,description="So much grief... So much pain. It binds us to this place. His melodies once soothed us, but now they are drowned out by the din of violence. Please help us. Follow the sound of the lyre. He will guide you.",objectivesText="Quell the restless spirits inside Windrunner Spire. Progress: Please... help us.",starts={{npcID=256875,x=0.354,y=0.79,zoneID=15968}},ends={{npcID=256875,x=0.354,y=0.79,zoneID=15968}},coords={x=0.354,y=0.79,source="quest_giver",zoneID=15968},questType="world",worldTaskTitle="Windrunner Spire: Haunting Melodies",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
[93904] = {id=93904,name="Defying Gravity",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16648,mapID=2527,description="Now, we descend. The Void energy below is unlike any I've felt before, as if gravity itself yields to the Void. Once you enter the cave, its influence will be upon you. Kalgorg has already slain and claimed power from the creatures within. Their violent deaths have left behind some kind of cursed terrain. But we must proceed and claim the power within. Fill the reliquary to the brim. I know not what to expect from my voidwalker. We will need all the power we can manage.",objectivesText="Gather Void energy within the Lair of Predaxas.",starts={{x=0.48,y=0.784,mapID=2405}},ends={{x=0.48,y=0.784,mapID=2405}},coords={mapID=2405,x=0.48,y=0.784},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Void Power Collected"},{orderIndex=4,type=0,amount=1,objectID=245756,text="Activate the Gravity Anomaly to travel up"}},worldTaskTitle="Defying Gravity",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93905] = {id=93905,name="Ongoing Stoppage",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15458,mapID=2405,description="The Shadowguard may once have defied Xal'atath, but they're part of her army now. Whatever they're doing with the energies gathered here must be stopped. Put down their soldiers, harvesters, and machines. I'll do the same, and meet you deeper within.",objectivesText="Slay Shadowguard and disrupt the Manaforge at the Ethereum Refinery.",starts={{x=0.374,y=0.751,mapID=2405}},ends={{x=0.374,y=0.751,mapID=2405}},coords={mapID=2405,x=0.374,y=0.751},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Manaforge Disrupted"},{orderIndex=1,type=2,amount=10,objectID=509568,text="Manaturret Destroyed"}},worldTaskTitle="Ongoing Stoppage",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[94361] = {id=94361,name="The Abundant Life",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2437,description="You are ready, acolyte! Ready to spread your wings or what have you? I have projected my presence into today's most active and tumultuous lands, rummaging about their natures and environs for areas ripe with abundance. With a little provocation from me, these forgotten corners are blooming bright with glorious harvestables! Seek me out! A crypt of phantasms in Eversong! A grove of verdant flora in Harandar! Even a quarry of living rock in Voidstorm! And, of course, right here too!",objectivesText="Complete each Abundance event once. They are located in Eversong, Zul'Aman, Harandar, and Voidstorm. Progress: Temperance, acolyte. There is still more abundance to be collected yet.",starts={{npcID=242704,x=0.316,y=0.26,zoneID=15947}},ends={{npcID=248658,x=0.66,y=0.616,zoneID=15355},{npcID=257632,x=0.388,y=0.532,zoneID=15458},{npcID=257633,x=0.568,y=0.658,zoneID=15968}},coords={x=0.316,y=0.26,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="The Abundant Life"},
[94385] = {id=94385,name="Void Assaults: Eversong Woods",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="We are seeing a Void Assault in Eversong. We need you to head out immediately to counter these threats. I will mark the strikes on your map as our scouts identify them and direct your efforts from here.",objectivesText="Disrupt the Void Strikes around Eversong Woods.",starts={{npcID=257411,x=0.48,y=0.496,zoneID=15969}},ends={{npcID=257411,x=0.48,y=0.496,zoneID=15969}},coords={x=0.48,y=0.496,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Void Assaults: Eversong Woods"},
[94386] = {id=94386,name="Void Assaults: Zul'Aman",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="My scouts report a Void Assault in Zul'Aman. We need your help to counter these threats. I will direct you, and my scouts will continue to mark new activities on your map.",objectivesText="Disrupt the Void Strikes around Zul'Aman. Progress: We will triumph over these foes!",starts={{npcID=257415,x=0.48,y=0.498,zoneID=15969}},ends={{npcID=257415,x=0.48,y=0.498,zoneID=15969}},coords={x=0.48,y=0.498,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Void Assaults: Zul'Aman"},
[94417] = {id=94417,name="Crests of the Dawn",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Using what I've learned from Silvermoon's artisans, Cuzolth and I can infuse your gear with additional power! Powerful equipment requires Dawncrests to upgrade it to its full potential. These crests are rewarded through many different activities. Dawncrests have five tiers, and more dangerous tasks reward you with higher-tier crests. Adventurer Dawncrests are the lowest tier, but still quite powerful! Bring me thirty Adventurer Dawncrests and we can help you upgrade your gear further.",objectivesText="Acquire 30 Adventurer Dawncrests by defeating unique creatures, completing world activities, or by looting caches. Speak to Cuzolth to upgrade an Adventurer track item using those crests, then return to Vaskarn in Silvermoon. Progress: If you're having a hard time finding Adventurer Dawncrests, you can search for hidden treasures around Eversong, Zul'Aman, Harandar, and Voidstorm. There's no shortage of those treasures!",starts={{npcID=239676,x=0.486,y=0.618,zoneID=15969}},ends={{npcID=239676,x=0.486,y=0.618,zoneID=15969}},coords={x=0.486,y=0.618,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Crests of the Dawn"},
[94418] = {id=94418,name="Crest Transmutation",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Did you know that crests can be transmuted into different tiers? If you find yourself with crests that are too powerful for the gear you've acquired, I can help you transmute those crests into lower tiers that you can use. And once all of your gear is sufficiently powerful, I'll be able to transmute your spare lower crests into higher ones! Let's practice the transmutation process. Here's a few Veteran Dawncrests. Speak to me and I can transform them into Adventurer Dawncrests for you.",objectivesText="Bring 10 Veteran Dawncrests to Vaskarn in Silvermoon, then trade them for a Bundle of Adventurer Dawncrests. Progress: If you lose those Veteran Dawncrests, you can find more from powerful creatures around Eversong, Zul'Aman, Harandar, and Voidstorm. I've heard there's quite a variety of them!",starts={{npcID=239676,x=0.486,y=0.618,zoneID=15969}},ends={{npcID=239676,x=0.486,y=0.618,zoneID=15969}},coords={x=0.486,y=0.618,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Crest Transmutation"},
[94425] = {id=94425,name="Bleed the Spire",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15458,mapID=2405,objectivesText="Speak to Scout Adaephus Elite Voidspire forces slain Summoning Pylons shattered Front Pylons Completed Rear Pylons Completed Right Pylon Left Pylon",starts={{x=0.488,y=0.598,mapID=2405}},ends={{x=0.488,y=0.598,mapID=2405}},coords={mapID=2405,x=0.488,y=0.598},questType="world",db2Objectives={{orderIndex=1,type=21,amount=8,objectID=5996,text="Elite Voidspire forces slain"},{orderIndex=2,type=2,amount=8,objectID=618960,text="Summoning Pylons shattered"},{orderIndex=0,type=0,amount=1,objectID=257704,text="Speak to Scout Adaephus"},{orderIndex=3,type=0,amount=5,objectID=258664,text="Front Pylons Completed"},{orderIndex=4,type=0,amount=5,objectID=257814,text="Rear Pylons Completed"},{orderIndex=5,type=0,amount=1,objectID=258662,text="Right Pylon"},{orderIndex=6,type=0,amount=1,objectID=258663,text="Left Pylon"}},worldTaskTitle="Bleed the Spire",db2QuestInfoID=111,db2QuestInfoName="Elite World Quest"},
[94430] = {id=94430,name="Adventuring Gear",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description=", you're just in time! I was exchanging research notes with the artisans here in Silvermoon all day. Did you know they can infuse weapons and armor with the power of the dawn itself? Fascinating! I've been itching to put some of these new techniques to the test. Bring me a piece of Adventurer equipment and I'll let you know what we need to make it more powerful. There should be plenty of people in Silvermoon and beyond willing to reward you with some Adventurer equipment in exchange for your aid.",objectivesText="Obtain a piece of Adventurer track gear, then return to Vaskarn in Silvermoon.",starts={{npcID=239676,x=0.486,y=0.618,zoneID=15969}},ends={{npcID=239676,x=0.486,y=0.618,zoneID=15969}},coords={x=0.486,y=0.618,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Adventuring Gear"},
[94432] = {id=94432,name="Veteran Equipment",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="We have only just begun to scratch the surface of how powerful your gear can become! However, every piece of equipment has a limit to how much it can be upgraded. The more powerful an item is at its baseline, the more powerful it will become as we upgrade it. An item's upgrade track determines which crests we must use to upgrade it. Bring me a piece of Veteran equipment this time along with some Veteran Dawncrests. Just like before, Cuzolth will help you upgrade the item using those crests.",objectivesText="Obtain a piece of Veteran track gear and 10 Veteran Dawncrests. Speak to Cuzolth to upgrade a Veteran track item using those crests, then return to Vaskarn in Silvermoon. Progress: If you're having trouble finding a piece of Veteran equipment, try completing a Heroic dungeon or a challenging weekly activity in Eversong, Zul'Aman, Harandar, or Voidstorm. You can find more powerful gear this way!",starts={{npcID=239676,x=0.486,y=0.618,zoneID=15969}},ends={{npcID=239676,x=0.486,y=0.618,zoneID=15969}},coords={x=0.486,y=0.618,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Veteran Equipment"},
