[94581] = {id=94581,name="Stand Your Ground",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16648,mapID=2405,objectivesText="Complete the entire Stormarion Assault Event Wave 1 Complete Wave 2 Complete Wave 3 Complete Defense Position activated",starts={{x=0.268,y=0.679,mapID=2405}},ends={{x=0.268,y=0.679,mapID=2405}},coords={mapID=2405,x=0.268,y=0.679},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Complete the entire Stormarion Assault Event"},{orderIndex=1,type=0,amount=1,objectID=248313,text="Wave 1 Complete"},{orderIndex=2,type=0,amount=1,objectID=248315,text="Wave 2 Complete"},{orderIndex=3,type=0,amount=1,objectID=248331,text="Wave 3 Complete"},{orderIndex=5,type=0,amount=1,objectID=248335,text="Defense Position activated"}},worldTaskTitle="Stand Your Ground",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
