[94790] = {id=94790,name="Research Console: Exploring the Void",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15458,mapID=2405,description="No rest for the researchers, as they say. As much as I would love to go traipsing around this blasted voidscape, I need to remain at this post. But you! You can be our eyes and ears in the abyss. Go and explore the Voidstorm , maybe we can find some additional samples to feed into the console.",objectivesText="Complete 3 World Quests for Void Researcher Anomander in Howling Ridge. Progress: Back so soon?",starts={{npcID=248328,x=0.526,y=0.728,zoneID=15458}},ends={{npcID=248328,x=0.526,y=0.728,zoneID=15458}},coords={x=0.526,y=0.728,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="Research Console: Exploring the Void"},
[94796] = {id=94796,name="Curing Curse Resistance",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Now that the Hoarder is gone, the fish population has boomed. There's a flood of fish with no curse at all! Captain Tokka wants to study these curse-resistant fish. Go and collect a few of their livers so we can see what keeps them swimming. If we want to use the venom-curse for ourselves, we need more cursed fish!",starts={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},ends={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},coords={x=0.516,y=0.498,source="quest_giver",zoneID=16365},questType="world",worldTaskTitle="Curing Curse Resistance"},
[94798] = {id=94798,name="Ssak'mozek's Desire",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Captain Tokka finished the lure for Ssak'mozek . It's time to kill the beast! Take the lure into the marsh, near the wreck of Pa'ku's Talon. Ready yourself, then place it on the rocks there. Ssak'mozek will be drawn to the lure. Kill it.",starts={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},ends={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},coords={x=0.516,y=0.498,source="quest_giver",zoneID=16365},questType="world",worldTaskTitle="Ssak'mozek's Desire"},
[94800] = {id=94800,name="Crushed Crabs",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Hegvosh the Hoarder is back! He's already started killing anything that gets in his way. This time, he's stomped on all of our crab traps in the south. Salvage any working trap pieces you find. We'll need to rebuild them.",starts={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},ends={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},coords={x=0.516,y=0.498,source="quest_giver",zoneID=16365},questType="world",worldTaskTitle="Crushed Crabs"},
[94802] = {id=94802,name="Death from the Dead",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Ssak'mozek always has three heads. Captain Tokka 's lure targets each of them. The next piece of the lure is ethereal beads from ghosts on the Isle. They exist somewhere between here and the beyond and shine in just the right way that the hydra can't ignore them. Ye can find some of these beads in the Crypt of the Lost Mason. Be careful--the ghosts may not like you entering that place.",starts={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},ends={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},coords={x=0.516,y=0.498,source="quest_giver",zoneID=16365},questType="world",worldTaskTitle="Death from the Dead"},
[94803] = {id=94803,name="Going for the Crown",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="The final pieces of Captain Tokka 's hydra lure are feathers from the Children of Ula'tek themselves. Ssak'mozek is trained to listen to the orders of these monsters. It lies in wait for them to call it from the murky depths. The lure can't work without something tying it to Ssak'mozek's masters. Any of the children at the Gate of the Eastern Fang will have feathers perfect for the lure. Bring as many as you can.",starts={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},ends={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},coords={x=0.516,y=0.498,source="quest_giver",zoneID=16365},questType="world",worldTaskTitle="Going for the Crown"},
[94804] = {id=94804,name="A Collection of Rot",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Have you noticed fewer fish on the south side of Atal'Utek lately? That's the Hoarder at work. He's this big ugly sea giant we can't seem to shake. You'll know you've found him when you see piles of dead fish rotting away. Make him think twice about taking too much from these waters.",starts={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},ends={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},coords={x=0.516,y=0.498,source="quest_giver",zoneID=16365},questType="world",worldTaskTitle="A Collection of Rot"},
[94805] = {id=94805,name="The New Hoard, Poached",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="The Children of Ula'tek eat venom-cursed fish straight from the water. Now that we've made the fish stronger, the children have gone into a feeding frenzy! Captain Tokka says to stop the poaching. The children have plenty of venom already!",starts={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},ends={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},coords={x=0.516,y=0.498,source="quest_giver",zoneID=16365},questType="world",worldTaskTitle="The New Hoard, Poached"},
[94806] = {id=94806,name="Wriggling and Wet",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Captain Tokka wants us to fish for Ssak'mozek. The Children of Ula'tek raise a hydra more vicious and venom-cursed than all the rest. We've caught and killed it before, but they always raise another and give it the same name: Ssak'mozek. We're going to craft one of Tokka's best lures to draw it in. Start by collecting the legs of leeches. When broken, they have a smell the children and their creations cannot resist.",starts={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},ends={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},coords={x=0.516,y=0.498,source="quest_giver",zoneID=16365},questType="world",worldTaskTitle="Wriggling and Wet"},
[94876] = {id=94876,name="Show Some Backbone",expansion=11,mapID=2512,questType="world",db2Objectives={{orderIndex=1,type=0,amount=100,objectID=259439,text="Secret Hog Credit"}},worldTaskTitle="Show Some Backbone",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[94967] = {id=94967,name="Ki'clak Snack Attack",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,mapID=2512,starts={{x=0.696,y=0.565,mapID=2512}},ends={{x=0.696,y=0.565,mapID=2512}},coords={mapID=2512,x=0.696,y=0.565},questType="world",db2Objectives={{orderIndex=0,type=1,amount=10,objectID=267085,text="Swirling Ectoplasm collected"},{orderIndex=1,type=0,amount=1,objectID=256686,text="Ki'clak Snack obtained"},{orderIndex=2,type=0,amount=1,objectID=256872,text="Ki'clak fed"}},worldTaskTitle="Ki'clak Snack Attack",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
