[95114] = {id=95114,name="Prey: A Crimson Summons",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Ah, $p. I have been looking for you. My... contacts have told me much regarding your continued attempts to defend our beloved city. But there is another way. Come, join me in Murder Row and we can get to work.",objectivesText="Meet with Astalor Bloodsworn in Murder Row.",starts={{npcID=259865,x=0.516,y=0.7,zoneID=15458},{npcID=259865,x=0.476,y=0.71,zoneID=15969}},ends={{npcID=246231,x=0.566,y=0.654,zoneID=15969}},coords={x=0.516,y=0.7,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="Prey: A Crimson Summons"},
[95175] = {id=95175,name="Anchoring the Defense",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="We need your help to activate the Singularity Anchor. With proper defenses we can counter enemy assaults long enough to activate the device. If the Anchor is destroyed our efforts will be halted. Do what you can to help us.",objectivesText="Complete the Stormarion Assault event. Progress: Have you helped us activate the Singularity Anchor?",starts={{npcID=248114,x=0.268,y=0.68,zoneID=15458}},ends={{npcID=248114,x=0.268,y=0.68,zoneID=15458}},coords={x=0.268,y=0.68,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="Anchoring the Defense"},
[95245] = {id=95245,name="Midnight: World Tour",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The immediate danger has passed, but there is still much to be done. Go out and work with our allies to secure what ground we have made against the darkness. Whether it is in Azeroth or beyond, there is still much to be done.",objectivesText="Complete faction features in Midnight zones.",starts={{npcID=235787,x=0.454,y=0.704,zoneID=15969}},ends={{npcID=235787,x=0.454,y=0.704,zoneID=15969}},coords={x=0.454,y=0.704,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Midnight: World Tour",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[95253] = {id=95253,name="Shocking Appetites",expansion=11,mapID=2512,questType="world",db2Objectives={{orderIndex=1,type=0,amount=3,objectID=260227,text="Deepwater Venom-Spewer fed to death"},{orderIndex=2,type=0,amount=4,objectID=260303,text="Serpent fed 01"},{orderIndex=0,type=14,amount=1,objectID=223651,text="Gather Zapgut Glands to feed to Venom-Spewers"},{orderIndex=3,type=0,amount=4,objectID=260301,text="Serpent fed 02"},{orderIndex=4,type=0,amount=4,objectID=260302,text="Serpent fed 03"}},worldTaskTitle="Shocking Appetites",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[95268] = {id=95268,name="New Tools, New Heights",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="There is another sort of Void power I know you will be interested in. An Ascendant Voidcore is difficult to come by, and even more difficult to work. With the Voidforge completed, I can now weave a magnificent Nilhammer capable of such things. Of course, I will need you to help with the materials. It will take time. Take this chunk of Hungering Oblivium . It can devour moments of extreme violence to be catalyzed to new heights of power, but I don't think you'll have any trouble managing that, will you?",objectivesText="Catalyze the Hungering Oblivium with violence by defeating Midnight Season 1 raid bosses or completing Mythic+ dungeons and Bountiful Delves. Progress: Have you fed your pet rock yet, <name>? I would not suggest leaving Oblivium on your person for extended periods of time...",starts={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},ends={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},coords={x=0.512,y=0.684,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="New Tools, New Heights",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[95269] = {id=95269,name="Feeding the Nilhammer",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Our nascent Nilhammer coalesces! But I will need to weave the Void energies from more Hungering Oblivium into it before it can fully take form. Luckily I have prepared another piece for you to catalyze. Extreme violence, remember?",objectivesText="Catalyze the Hungering Oblivium with violence by defeating Midnight Season 1 raid bosses or completing Mythic+ dungeons and Bountiful Delves.",starts={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},ends={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},coords={x=0.512,y=0.684,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="Feeding the Nilhammer",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[95271] = {id=95271,name="The Ascendant Nilhammer",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,starts={{npcID=243907,x=0.512,y=0.684,mapID=2405}},ends={{npcID=243907,x=0.512,y=0.684,mapID=2405}},coords={x=0.512,y=0.684,source="quest_giver",mapID=2405},questType="world",worldTaskTitle="The Ascendant Nilhammer",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[95279] = {id=95279,name="Nebulous Voidcores: Gold",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,objectivesText="Progress: Back for more Nebulous Voidcores ? I have them prepared, but I do expect you to share the burden of my expenses. And then some. Why shouldn't your delightful affinity for violence pay dividends, after all? Even in the Voidstorm we can find uses for the gold. It has the most interesting properties when subjected to a touch of Void energy under the right conditions!",starts={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},ends={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},coords={x=0.512,y=0.684,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="Nebulous Voidcores: Gold"},
[95290] = {id=95290,name="Nebulous Voidcores: Voidlight Marl",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,objectivesText="Progress: Back for more Nebulous Voidcores ? I have them prepared, but I do expect you to share the burden of my expenses. And then some. Why shouldn't your delightful affinity for violence pay dividends, after all? Voidlight Marl is a fascinating substance! I am always happy to have more to experiment with. It is usually difficult to come by such Light-touched reagents in the Voidstorm .",starts={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},ends={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},coords={x=0.512,y=0.684,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="Nebulous Voidcores: Voidlight Marl"},
[95304] = {id=95304,name="Nebulous Voidcores: Veteran Dawncrest",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,objectivesText="Progress: Back for more Nebulous Voidcores ? I have them prepared, but I do expect you to share the burden of my expenses. And then some. Why shouldn't your delightful affinity for violence pay dividends, after all? Those crests you use to empower equipment could be put to great use in my workshop. I can always use new materials to experiment with.",starts={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},ends={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},coords={x=0.512,y=0.684,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="Nebulous Voidcores: Veteran Dawncrest"},
[95324] = {id=95324,name="The War Beyond the Roots",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Your actions in Harandar caused quite an uproar. The elders are up in arms. The rootwardens are worried. It's really quite exhausting. But there is good news as well. Orweyna has heard rumblings from every corner of the roots. She tells me of haranir who wish to see the world as she does--who feel compelled to seek the goddess beyond the boughs of Harandar. I will handle things in Harandar. Go to your leaders. Tell them that the haranir are ready to join the fight.",objectivesText="Bring word to Lor'themar in the Sanctum of Light.",starts={{npcID=255819,x=0.366,y=0.686,zoneID=15969}},ends={{npcID=235787,x=0.454,y=0.704,zoneID=15969}},coords={x=0.366,y=0.686,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="The War Beyond the Roots",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[95373] = {id=95373,name="A Nebulous Endeavour",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="I see you haven't come across a Nebulous Voidcore before. I can now weave them for you from the energies of the Catalyst as they accumulate, but you'll have to provide raw reagents. With the Voidcore in hand, you'll have to seek out powerful enemies in order to transmute it into useful equipment. Its capable of capturing part of their essence to become something more powerful that you can put to use in the battles ahead.",objectivesText="Transmute a Nebulous Voidcore into equipment after defeating a Midnight Season 1 raid boss, completing a Mythic+ dungeon, or opening a Delve's Bountiful Coffer. Progress: Back already, <name>? Were you able to transmute the Nebulous Voidcore?",starts={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},ends={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},coords={x=0.512,y=0.684,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="A Nebulous Endeavour",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[95381] = {id=95381,name="Fire in the Sky",expansion=11,mapID=2512,questType="world",db2Objectives={{orderIndex=1,type=0,amount=10,objectID=260832,text="Bone Cages destroyed"},{orderIndex=4,type=0,amount=30,objectID=260379,text="Eggs burned"},{orderIndex=2,type=0,amount=20,objectID=260869,text="Children of Ula'tek slain"},{orderIndex=5,type=0,amount=12,objectID=260870,text="Serpents slain"},{orderIndex=3,type=0,amount=99,objectID=260869,text="Children of Ula'tel slain HIDDEN"},{orderIndex=6,type=0,amount=99,objectID=260870,text="Serpents slain HIDDEN"},{orderIndex=7,type=0,amount=1,objectID=260927,text="Stage 03 Begin Conversation"},{orderIndex=0,type=0,amount=1,objectID=260380,text="Ride the War Eagle"}},worldTaskTitle="Fire in the Sky",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
