[95520] = {id=95520,name="Purging the Vaults",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2509,description="De fiends of dis temple would see us all dead. We are all dat stands between them and de mainland, you understand? We hold dem here. Not one scale, not one bony finger, none of them will leave dis temple while we breathe. Get out there and cut them down.",starts={{npcID=262798,x=0.472,y=0.608,zoneID=16535},{npcID=267635,x=0.586,y=0.458,zoneID=16365}},ends={{npcID=262798,x=0.472,y=0.608,zoneID=16535}},coords={x=0.472,y=0.608,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="Purging the Vaults",db2QuestInfoID=284,db2QuestInfoName="Meta Quest"},
