[95549] = {id=95549,name="Raising Magical Alarms",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="I have a request. These Ritual Sites invoke some interesting magic. I would like you to obtain some sample readings. You don't need to concern yourself with the details. Just visit the area I will mark on your map and press the button. You may end up garnering some extra attention when you do so.",objectivesText="Use Lady Darkglen's device in a Ritual Site. Progress: That is the look of success.",starts={{npcID=257416,x=0.478,y=0.496,zoneID=15969}},ends={{npcID=257416,x=0.478,y=0.496,zoneID=15969}},coords={x=0.478,y=0.496,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Raising Magical Alarms"},
[95550] = {id=95550,name="Thin Their Ranks",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="I don't like it. We have far too many scouts returning wounded from these so-called ritual sites. Thin out the ranks of these cultists.",objectivesText="Defeat enemies in a Ritual Site. Progress: Is the job done?",starts={{npcID=257411,x=0.48,y=0.496,zoneID=15969}},ends={{npcID=257411,x=0.48,y=0.496,zoneID=15969}},coords={x=0.48,y=0.496,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Thin Their Ranks"},
[95552] = {id=95552,name="Dark Obelisk Investigation",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description=", we have reports that the leaders of the Ritual Sites are using dark obelisks to bolster their forces with malevolent boons. I need you to investigate the objects they are using to gain these boons.",objectivesText="Investigate the sources of the malevolent boons in a Ritual Site. Progress: What do you have to report?",starts={{npcID=257416,x=0.478,y=0.496,zoneID=15969}},ends={{npcID=257416,x=0.478,y=0.496,zoneID=15969}},coords={x=0.478,y=0.496,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Dark Obelisk Investigation"},
[95553] = {id=95553,name="Manifested Density",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="I'm hearing strange murmurings from my scouts. Some are claiming that strange manifestations are appearing and cursing intruders. Could I ask you to investigate and see if there is any truth to these rumors?",objectivesText="Complete a Ritual Site.",starts={{npcID=257411,x=0.48,y=0.496,zoneID=15969}},ends={{npcID=257411,x=0.48,y=0.496,zoneID=15969}},coords={x=0.48,y=0.496,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Manifested Density"},
