[96004] = {id=96004,name="Prey: A Slithering Threat",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15958,mapID=2393,description="Do you feel it, $p? We are being watched. I do not know by whom, or to what end, but it appears that our... efforts have drawn fresh attention. Go out and survey the field. Let us test the mettle of these newcomers.",starts={{npcID=246231,x=0.566,y=0.654,zoneID=15969}},ends={{npcID=246231,x=0.566,y=0.654,zoneID=15969}},coords={x=0.566,y=0.654,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Prey: A Slithering Threat",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[96048] = {id=96048,name="The Time to Strike",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description=", Your efforts against the recent void and ethereal incursions have paid off. It's time we take the fight to them. Meet me at the Ranger-Captain's strike station in Silvermoon. Do not delay. Riftblade Maella",starts={{npcID=263929,x=0.484,y=0.646,zoneID=15969}},ends={{npcID=263479,x=0.476,y=0.51,zoneID=15969}},coords={x=0.484,y=0.646,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="The Time to Strike"},
