[96223] = {id=96223,name="The Magisters' Call",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The Magisters request your presence at Thalassian University. Please proceed to the upper levels overlooking the harbor. This concerns a private matter of minor urgency.",starts={{npcID=265903,x=0.478,y=0.516,mapID=2393}},ends={{npcID=264063,x=0.388,y=0.486,mapID=2393},{npcID=264064,x=0.388,y=0.486,mapID=2393}},coords={x=0.478,y=0.516,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="The Magisters' Call",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[96267] = {id=96267,name="Ancestral Gems",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="When de Children of Ula'tek seized dis temple, many of my ancestors died defendin' it. Sacred relics were seized by de snakes! Even now, dey twist those items into foul magic! Among these items were some gems of great power. Search de vaults, ritual chambers, and every deep corner of de temple and recover any gems you find.",starts={{npcID=264611,x=0.504,y=0.638,zoneID=16535}},ends={{npcID=264611,x=0.504,y=0.638,zoneID=16535}},coords={x=0.504,y=0.638,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="Ancestral Gems",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96268] = {id=96268,name="Marsh Mana Spores",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16943,mapID=2600,starts={{x=0.631,y=0.55,mapID=2600}},ends={{x=0.631,y=0.55,mapID=2600}},coords={mapID=2600,x=0.631,y=0.55},questType="world",db2Objectives={{orderIndex=1,type=1,amount=5,objectID=276276,text="Mana Spores gathered"},{orderIndex=0,type=0,amount=1,objectID=264323,text="Jump on a Bouncy Mushroom"}},worldTaskTitle="Marsh Mana Spores",db2QuestInfoID=296,db2QuestInfoName="World Quest (Short Duration)"},
[96271] = {id=96271,name="Cursed Existence",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16535,mapID=2509,description="When de poison spread through dis temple, many of our ancestors fell trying to defend dis place. Now Nek'zali has ensnared their spirits to serve her in restoring Ula'tek. Put de cursed spirits to rest so dey may pass beyond dis place.",starts={{x=0.506,y=0.638,mapID=2509,npcID=264611}},ends={{x=0.506,y=0.638,mapID=2509,npcID=264611}},coords={mapID=2509,x=0.506,y=0.638},questType="world",worldTaskTitle="Cursed Existence",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96272] = {id=96272,name="Mashing Mushroom Mana Machines",expansion=11,mapID=2600,questType="world",db2Objectives={{orderIndex=0,type=2,amount=8,objectID=651860,text="Harvesting Machines deactivated"}},worldTaskTitle="Mashing Mushroom Mana Machines",db2QuestInfoID=296,db2QuestInfoName="World Quest (Short Duration)"},
[96273] = {id=96273,name="A Balance Paid in Blood",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=16535,mapID=2509,description="De Children of Ula'tek have upset de balance of de spirit world. Many spirits are angry and demand justice before dey can move on. De snakes' blood will restore de balance! Slay de Children of Ula'tek and all dat aid dem here in de temple.",starts={{npcID=264611,x=0.504,y=0.638,zoneID=16535}},ends={{npcID=264611,x=0.504,y=0.638,zoneID=16535}},coords={x=0.504,y=0.638,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="A Balance Paid in Blood",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96275] = {id=96275,name="Wading In",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="Too many spirits here have succumbed to de dark charms of Nek'zali, but there's still hope to save others. Place spirit guardians throughout de lakes of venom so dey may offer sanctuary to spirits nearby. De venom lakes are deadly, so go prepared!",starts={{npcID=264611,x=0.504,y=0.638,zoneID=16535}},ends={{npcID=264611,x=0.504,y=0.638,zoneID=16535}},coords={x=0.504,y=0.638,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="Wading In",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96276] = {id=96276,name="Dark Charms",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="De Children of Ula'tek play cruel games on de spirits here. Dey use dark charms to keep dem trapped and tormented. De charms are hidden throughout de temple. Find and burn them, so de spirits here can find peace.",starts={{npcID=264611,x=0.504,y=0.638,zoneID=16535}},ends={{npcID=264611,x=0.504,y=0.638,zoneID=16535}},coords={x=0.504,y=0.638,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="Dark Charms",db2QuestInfoID=1,db2QuestInfoName="Group"},
