[96388] = {id=96388,name="Joining the Abyss Anglers",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Ya ever heard of de Abyss Anglers? Forest tribes have been hunting de land as well as de waters for generations. Don't be shy, hash'ura. Grab a suit and go for a dive!",objectivesText="Talk to Depthdiver Jeju to join an Abyss Anglers dive. Catch any 3 fish with your harpoon, recover 1 Sunken Artifact, and use the Surface! ability to return safely. Progress: De suit fit okay?",starts={{npcID=240195,x=0.682,y=0.202,zoneID=15947}},ends={{npcID=240195,x=0.682,y=0.202,zoneID=15947}},coords={x=0.682,y=0.202,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Joining the Abyss Anglers"},
