[96472] = {id=96472,name="The Nexus-Captain",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,mapID=2600,description="The Hal'hadar may not know we are here yet, but they still hold the advantage. Nexus-Captain Leth'ir and his associate, Mertei, are just over this ridge and surrounded by a small army. If you can rally enough allies and catch their leaders off guard, we will deal a devastating blow before they know what hit them. Proceed with caution, , and make sure you are not alone.",starts={{npcID=264028,x=0.708,y=0.622,zoneID=16943}},ends={{npcID=264024,x=0.484,y=0.82,zoneID=16943}},coords={x=0.708,y=0.622,source="quest_giver",zoneID=16943},questType="world",worldTaskTitle="The Nexus-Captain",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96474] = {id=96474,name="Prey: Something for Astalor",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="$p! Ah, we haven't met. Not formally. I've overheard some of your discussions with Magister Astalor while I was, er, scrubbing the floors. You seem like quite the competent operator! That makes two of us. Usually. I'm a bit... preoccupied at the moment, what with the local wildlife and all. Maybe you can poke around for us?",starts={{npcID=265267,x=0.582,y=0.486,zoneID=16365}},ends={{npcID=265267,x=0.582,y=0.486,zoneID=16365}},coords={x=0.582,y=0.486,source="quest_giver",zoneID=16365},questType="world",worldTaskTitle="Prey: Something for Astalor"},
[96496] = {id=96496,name="The Road Not Taken Twice",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,mapID=2599,description="During our surveys of this iced desert, our scouts identified two areas worth keeping an eye on, but with a major problem: they're only accessible through single points of entry. Before I'm comfortable sending out more forces, we need to secure their exits. We've been working on teleportation crystals for faster local travel that leverage the domanaar's existing portal network, and we're close to a solution. You just need to field test them. Set up these prototype rift slippers and report back.",starts={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},ends={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},coords={x=0.596,y=0.218,source="quest_giver",zoneID=16900},questType="world",worldTaskTitle="The Road Not Taken Twice"},
[96497] = {id=96497,name="Spatial Reasoning",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,mapID=2599,description="The domanaar are more entrenched here than we thought and these storms refuse to relent even for a moment. We've finally figured out how to hijack their portal network for short range traversal thanks to your efforts setting up the rift slippers. Now we just need help setting up our portal bridges . Here are four strategic locations, including this outpost, for you to set up the portal bridges . Once active, you'll be able to more swiftly respond to threats as they arise. Time to get to work.",starts={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},ends={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},coords={x=0.596,y=0.218,source="quest_giver",zoneID=16900},questType="world",worldTaskTitle="Spatial Reasoning"},
[96522] = {id=96522,name="Oh Captain, Die Captain!",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16943,mapID=2600,starts={{x=0.77,y=0.757,mapID=2600}},ends={{x=0.77,y=0.757,mapID=2600}},coords={mapID=2600,x=0.77,y=0.757},questType="world",worldTaskTitle="Oh Captain, Die Captain!",db2QuestInfoID=289,db2QuestInfoName="World Boss"},
[96528] = {id=96528,name="Prey: Anguish from Beyond",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="$p! I tried to sneak away from those snakes, but one of them slithered up my pant leg and I blacked out for a bit. When I awoke, I was here... I wonder if there's anything in here that would interest Magister Astalor. Wait... what's that? That glowing... It looks like your crystal is interacting with something in this tomb!",starts={{npcID=265529,x=0.57,y=0.332,zoneID=16365}},ends={{npcID=265529,x=0.57,y=0.332,zoneID=16365}},coords={x=0.57,y=0.332,source="quest_giver",zoneID=16365},questType="world",worldTaskTitle="Prey: Anguish from Beyond"},
