[97215] = {id=97215,name="A Secondary Strike",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15458,mapID=2393,description="We have struck a major blow against our enemies. Still, they continue their assaults. Decimus and my riftwardens have targeted another world from which they launch these attacks. The bulk of our forces have temporarily withdrawn to the Voidstorm so that we may begin our assault on this second world. Our strike team awaits us at the Howling Ridge.",starts={{npcID=263479,x=0.476,y=0.51,mapID=2393}},ends={{npcID=263480,x=0.516,y=0.71,mapID=2405}},coords={x=0.476,y=0.51,source="quest_giver",mapID=2405},questType="world",worldTaskTitle="A Secondary Strike"},
[97256] = {id=97256,name="Knocking Off the Top (Heroic)",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16943,mapID=2599,description="Even the most ruthless of creatures falter when they see their greatest champions crumble to ash. Remind our enemies here just how quickly their leaders fall! Let them know just how unrelenting and vicious you monsters of Azeroth really are! Bring me the Void Commander's Emblems and I will reward you accordingly.",starts={{npcID=264879,x=0.598,y=0.218,zoneID=16900},{npcID=265303,x=0.484,y=0.82,zoneID=16943}},ends={{npcID=264879,x=0.598,y=0.218,zoneID=16900},{npcID=265303,x=0.484,y=0.82,zoneID=16943}},coords={x=0.598,y=0.218,source="quest_giver",zoneID=16900},questType="world",worldTaskTitle="Knocking Off the Top (Heroic)"},
[97321] = {id=97321,name="Slithering Spoils",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="I've got good news and bad news. Bad is that all those curios we dug up together? Melted. Good news? I've found some very interesting new poisons to work with. But let me explain what happened...",starts={{npcID=242381,x=0.524,y=0.78,mapID=2393}},ends={{npcID=242381,x=0.524,y=0.78,mapID=2393}},coords={x=0.524,y=0.78,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="Slithering Spoils"},
[97454] = {id=97454,name="Seasonal Refresher: Midnight",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Since the opening of the Coiling Isles, things have started to get interesting again in delves. See if our dear hosts have anything they can spare for those of us actually risking our necks and check the Delver's Guide for any updates. A quick refresher never hurt anyone.",starts={{npcID=242381,x=0.524,y=0.78,zoneID=15969}},ends={{npcID=242381,x=0.524,y=0.78,zoneID=15969}},coords={x=0.524,y=0.78,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Seasonal Refresher: Midnight",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[97482] = {id=97482,name="Fangs for the Memories",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2634,description="That snake monstrosity was vicious, with venom potent enough to burn through stone. We'll want to make sure we get our hands on the best gear we can before we think about taking it on. I've got some ideas about turning that venom to our own ends, though, so we can hit the ground running.",starts={{npcID=242381,x=0.524,y=0.78,mapID=2393}},ends={{npcID=242381,x=0.524,y=0.78,mapID=2393}},coords={x=0.524,y=0.78,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="Fangs for the Memories"},
[97945] = {id=97945,name="In the Catalyst's Shadow",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2405,description="Ah, ! Good. Now that you've helped me amass such a wealth of resources, it's time for me to pursue other... interests. What? You expected a more dramatic betrayal? Never! Don't worry, $p, while I may be occupied elsewhere, I'll never tire of watching your adventures. Adventures still bolstered by my gifts, of course. Many have shown interest, but I've only found one void elf... amusingly strange enough to mentor. Orin Straylight is the name. You'll find him by the Catalyst in Silvermoon.",starts={{npcID=243907,x=0.512,y=0.684,mapID=2405}},ends={{npcID=269987,x=0.4,y=0.646,mapID=2393}},coords={x=0.512,y=0.684,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="In the Catalyst's Shadow",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[97981] = {id=97981,name="Umbral Blessings of the Catalyst",expansion=11,mapID=2405,questType="world",worldTaskTitle="Umbral Blessings of the Catalyst",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
